import { ChevronDown, Edit3 } from 'lucide-react';
import { useMemo, useState } from 'react';
import type { Word } from 'entities/word/model/types';
import { Button } from 'shared/ui/Button';
import { FrequencyBadge } from 'shared/ui/FrequencyBadge';
import { HighlightedText } from 'shared/ui/HighlightedText';
import { Modal } from 'shared/ui/Modal';
import { PronunciationList } from 'shared/ui/PronunciationList';
import { UsageExamples } from 'shared/ui/UsageExamples';
import { WordImageGrid } from 'shared/ui/WordImageGrid';
import styles from './WordDetailsModal.module.sass';

export function WordDetailsModal({ word, onClose, onEdit }: { word: Word; onClose: () => void; onEdit?: () => void }) {
  const [examplesOpen,setExamplesOpen]=useState(true);
  const count=useMemo(()=>word.examples?.reduce((sum,g)=>sum+(g.translations?.length||0)+(g.phrases?.length||0)+g.examples.length,0)||0,[word.examples]);
  const images=word.images?.length?word.images:(word.image?[word.image]:[]);
  return <Modal title={word.word} onClose={onClose} wide actions={onEdit ? <Button onClick={onEdit}><Edit3 size={16}/>Edit</Button> : undefined}>
    <div className={styles.root}>
      <div className={styles.hero}>
        <div className={styles.imageArea}>{images.length?<WordImageGrid images={images} alt={word.word} square/>:<div className={styles.placeholder}>{word.word[0]?.toUpperCase()}</div>}</div>
        <div className={styles.summary}>
          <div className={styles.titleRow}><div className={styles.heading}><h1>{word.word}</h1><FrequencyBadge rank={word.frequencyRank}/></div></div>
          <PronunciationList word={word.word} transcription={word.transcription} audio={word.audio}/>
          <p className={styles.translation}>{word.translation}</p>
          <div className={styles.parts}>{(word.partsOfSpeech?.length?word.partsOfSpeech:[word.partOfSpeech]).map(item=><span key={item}>{item}</span>)}</div>
          {word.example&&<p className={styles.personal}><HighlightedText text={word.example} word={word.word}/></p>}
        </div>
      </div>
      <button className={styles.toggle} onClick={()=>setExamplesOpen(v=>!v)}><span>Dictionary details {count?`(${count})`:''}</span><ChevronDown className={examplesOpen?styles.open:''}/></button>
      {examplesOpen&&<div className={styles.examples}><UsageExamples groups={word.examples} word={word.word}/></div>}
    </div>
  </Modal>;
}
