import { useState } from 'react';
import { useData } from 'app/providers/DataProvider';
import type { Word, WordAudio, WordExampleGroup, WordPronunciation } from 'entities/word/model/types';
import { ImagePicker } from 'features/image-picker';
import { WordEnrichment } from 'features/translation-lookup';
import { Button } from 'shared/ui/Button';
import { Field, Input, Select, Textarea } from 'shared/ui/Form';
import { Modal } from 'shared/ui/Modal';
import styles from './WordEditor.module.sass';

const emptyTranscription: WordPronunciation = { american: '', british: '' };
const emptyAudio: WordAudio = { american: '', british: '' };

export function WordEditor({ word, initialFolderId, onClose }: { word?: Word; initialFolderId?: string; onClose: () => void }) {
  const { folders, createWord, updateWord } = useData();
  const [english, setEnglish] = useState(word?.word || '');
  const [russian, setRussian] = useState(word?.translation || '');
  const [folderId, setFolderId] = useState(word?.folderId || initialFolderId || folders[0]?.id || '');
  const [partsOfSpeech, setPartsOfSpeech] = useState<string[]>(word?.partsOfSpeech?.length ? word.partsOfSpeech : [word?.partOfSpeech || 'noun']);
  const [example, setExample] = useState(word?.example || '');
  const [examples, setExamples] = useState<WordExampleGroup[]>(word?.examples || []);
  const [transcription, setTranscription] = useState<WordPronunciation>(word?.transcription || emptyTranscription);
  const [audio, setAudio] = useState<WordAudio>(word?.audio || emptyAudio);
  const [images, setImages] = useState<string[]>(word?.images?.length ? word.images : word?.image ? [word.image] : []);
  const [frequencyRank, setFrequencyRank] = useState<number | null>(word?.frequencyRank ?? null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  function normalizeEnglish(value: string): string {
    return value.toLocaleLowerCase('en-US');
  }

  async function save(): Promise<void> {
    if (!english.trim() || !russian.trim() || !folderId) {
      setError('English word, Russian translation, and folder are required.');
      return;
    }
    setBusy(true); setError('');
    try {
      const body = {
        word: normalizeEnglish(english.trim()), translation: russian.trim(), folderId,
        partOfSpeech: partsOfSpeech[0] || 'other', partsOfSpeech, example, examples,
        transcription, audio, frequencyRank, images, image: images[0] || '', showImage: images.length > 0,
      };
      if (word) await updateWord(word.id, body); else await createWord(body);
      onClose();
    } catch (saveError) { setError(saveError instanceof Error ? saveError.message : 'Could not save word'); }
    finally { setBusy(false); }
  }

  return <Modal title={word ? 'Edit word' : 'Add word'} onClose={onClose} wide workspace>
    <div className={styles.form}>
      <section className={styles.detailsPane}>
        <div className={styles.fields}>
          <Field label="English">
            <Input value={english} onChange={event=>setEnglish(normalizeEnglish(event.target.value))} autoFocus autoComplete="off" autoCapitalize="none" spellCheck={false}/>
          </Field>

          <WordEnrichment
            english={english} russian={russian} onRussianChange={setRussian}
            transcription={transcription} onTranscriptionChange={setTranscription}
            audio={audio} onAudioChange={setAudio}
            partsOfSpeech={partsOfSpeech} onPartsOfSpeechChange={setPartsOfSpeech}
            examples={examples} onExamplesChange={setExamples}
            frequencyRank={frequencyRank} onFrequencyRankChange={setFrequencyRank}
            autoLookup
          />

          <Field label="Folder"><Select value={folderId} onChange={event=>setFolderId(event.target.value)}>{folders.map(folder=><option key={folder.id} value={folder.id}>{folder.name}</option>)}</Select></Field>

          <Field label="Personal example sentence"><Textarea value={example} onChange={event=>setExample(event.target.value)} placeholder="Optional personal example."/></Field>
        </div>
        <div className={styles.footer}>{error&&<div className={styles.error}>{error}</div>}<div className={styles.actions}><Button onClick={onClose}>Cancel</Button><Button variant="primary" onClick={()=>void save()} disabled={busy}>{busy?'Saving…':'Save word'}</Button></div></div>
      </section>
      <section className={styles.imagePane}><ImagePicker query={english} value={images} onChange={setImages} autoSearch/></section>
    </div>
  </Modal>;
}
