export const formatSeconds = (value: number | null) => value == null ? 'New' : `${value.toFixed(1)} s`;
export const scoreTone = (score: number) => score >= 75 ? 'good' : score >= 45 ? 'medium' : 'weak';
export const knowledgeLabel = (score: number) => score >= 75 ? 'Known' : score >= 45 ? 'Learning' : 'New';
