import { useState } from 'react';
import type { Folder } from 'entities/folder/model/types';
import { useData } from 'app/providers/DataProvider';
import { Button } from 'shared/ui/Button';
import { Field, Input } from 'shared/ui/Form';
import { Modal } from 'shared/ui/Modal';
import styles from './FolderEditor.module.sass';
export function FolderEditor({ folder, onClose }: { folder?: Folder; onClose: () => void }) {
 const {createFolder,updateFolder}=useData(); const [name,setName]=useState(folder?.name||'');const[icon,setIcon]=useState(folder?.icon||'📁');const[color,setColor]=useState(folder?.color||'#7c5cff');const[busy,setBusy]=useState(false);const[error,setError]=useState('');
 async function save(){if(!name.trim())return setError('Folder name is required.');setBusy(true);try{if(folder)await updateFolder(folder.id,{name,icon,color});else await createFolder({name,icon,color});onClose();}catch(e){setError(e instanceof Error?e.message:'Could not save folder');}finally{setBusy(false)}}
 return <Modal title={folder?'Edit folder':'New folder'} onClose={onClose}><div className={styles.form}><Field label="Folder name"><Input value={name} onChange={e=>setName(e.target.value)} autoFocus/></Field><div className={styles.row}><Field label="Icon"><Input value={icon} onChange={e=>setIcon(e.target.value)} maxLength={4}/></Field><Field label="Color"><Input type="color" value={color} onChange={e=>setColor(e.target.value)}/></Field></div>{error&&<div className={styles.error}>{error}</div>}<div className={styles.actions}><Button onClick={onClose}>Cancel</Button><Button variant="primary" onClick={()=>void save()} disabled={busy}>{busy?'Saving…':'Save folder'}</Button></div></div></Modal>;
}
