import { useEffect, useRef, useState } from 'react';
import { Check, ImageIcon, LoaderCircle, Search, Upload, X } from 'lucide-react';
import { api } from 'shared/api/apiClient';
import type { ImageProviderStatus, ImageResult, ImageSearchResponse } from 'shared/api/types';
import { Button } from 'shared/ui/Button';
import { Input } from 'shared/ui/Form';
import { WordImageGrid } from 'shared/ui/WordImageGrid';
import styles from './ImagePicker.module.sass';

interface ImagePickerProps {
  query: string;
  value: string[];
  onChange: (urls: string[]) => void;
  autoSearch?: boolean;
}
function mergeItems(current: ImageResult[], incoming: ImageResult[]): ImageResult[] { const seen=new Set(current.map(item=>item.id));const merged=[...current];for(const item of incoming){if(seen.has(item.id))continue;seen.add(item.id);merged.push(item)}return merged; }

export function ImagePicker({ query, value, onChange, autoSearch = false }: ImagePickerProps) {
  const [searchQuery,setSearchQuery]=useState(query); const [items,setItems]=useState<ImageResult[]>([]); const [searching,setSearching]=useState(false); const [loadingMore,setLoadingMore]=useState(false); const [providers,setProviders]=useState<ImageProviderStatus[]>([]); const [selectedId,setSelectedId]=useState<string|null>(null); const [status,setStatus]=useState('Select up to four images. Search results are stored locally when selected.');
  const fileRef=useRef<HTMLInputElement>(null); const pollTimerRef=useRef<number|null>(null); const searchVersionRef=useRef(0);
  useEffect(()=>setSearchQuery(query),[query]);
  useEffect(()=>{if(!autoSearch)return undefined;const normalized=query.trim();if(normalized.length<2)return undefined;const timer=window.setTimeout(()=>{setSearchQuery(normalized);void search(normalized)},500);return()=>window.clearTimeout(timer)},[query,autoSearch]);
  useEffect(()=>()=>{if(pollTimerRef.current!==null)window.clearTimeout(pollTimerRef.current)},[]);
  function stopPolling(){if(pollTimerRef.current!==null){window.clearTimeout(pollTimerRef.current);pollTimerRef.current=null}setLoadingMore(false)}
  function updateFromResponse(result:ImageSearchResponse){setItems(current=>mergeItems(current,result.items));setProviders(result.providers||[])}
  function scheduleProgressPoll(searchId:string,version:number){setLoadingMore(true);pollTimerRef.current=window.setTimeout(async()=>{try{const result=await api.imageSearchProgress(searchId);if(searchVersionRef.current!==version)return;updateFromResponse(result);if(result.complete){stopPolling();setStatus(result.items.length?`${result.items.length} verified images loaded.`:'No usable images found.');return}setStatus(`${result.items.length} images ready. Loading the rest…`);scheduleProgressPoll(searchId,version)}catch(error){if(searchVersionRef.current!==version)return;stopPolling();setStatus(error instanceof Error?error.message:'Could not load more images.')}},420)}
  async function search(queryOverride?:string){const normalized=(queryOverride??searchQuery).trim();if(!normalized)return;stopPolling();const version=++searchVersionRef.current;setSearching(true);setSelectedId(null);setItems([]);setProviders([]);setStatus('Searching Bing, DuckDuckGo and Flickr…');try{const result=await api.searchImages(normalized);if(searchVersionRef.current!==version)return;updateFromResponse(result);if(result.complete)setStatus(result.items.length?`${result.items.length} verified images loaded.`:'No usable images found.');else{setStatus(result.items.length?`${result.items.length} images ready. Loading the rest…`:'Preparing previews…');scheduleProgressPoll(result.searchId,version)}}catch(error){setStatus(error instanceof Error?error.message:'Image search failed.')}finally{if(searchVersionRef.current===version)setSearching(false)}}
  async function select(item:ImageResult){if(value.length>=4){setStatus('Maximum four images per word. Remove one before selecting another.');return}setSelectedId(item.id);setStatus('Saving a local copy…');try{const result=await api.saveRemoteImage(item.id);if(!value.includes(result.url))onChange([...value,result.url].slice(0,4));setStatus('Image added. You can select up to four.')}catch(error){setStatus(error instanceof Error?error.message:'Could not save image.')}finally{setSelectedId(null)}}
  async function upload(file:File){if(value.length>=4){setStatus('Maximum four images per word.');return}setSelectedId('upload');try{const result=await api.uploadImage(file);onChange([...value,result.url].slice(0,4));setStatus('Image uploaded and stored locally.')}catch(error){setStatus(error instanceof Error?error.message:'Upload failed.')}finally{setSelectedId(null)}}
  const saving=selectedId!==null;
  return <div className={styles.root}>
    <div className={styles.topPanel}><div className={styles.mediaRow}>
      <div className={styles.selectedPanel}>{value.length?<><WordImageGrid images={value} alt="Selected" compact/><div className={styles.selectedList}>{value.map((url,index)=><button type="button" key={url} onClick={()=>onChange(value.filter(item=>item!==url))} title={`Remove image ${index+1}`}><img src={api.imageUrl(url)} alt=""/><X size={13}/></button>)}</div><span className={styles.selectionCount}>{value.length}/4 selected</span></>:<div className={styles.empty}><ImageIcon/><span>No image selected</span></div>}</div>
      <div className={styles.controls}><div className={styles.search}><Input value={searchQuery} onChange={e=>setSearchQuery(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();void search()}}} placeholder="Image search query"/><Button onClick={()=>void search()} disabled={searching||saving}>{searching?<LoaderCircle className={styles.spinner} size={17}/>:<Search size={17}/>}Search photos</Button><Button onClick={()=>fileRef.current?.click()} disabled={searching||saving||value.length>=4}><Upload size={17}/>Upload</Button><input ref={fileRef} type="file" accept="image/*" hidden onChange={e=>{const file=e.target.files?.[0];if(file)void upload(file);e.target.value=''}}/></div>
      <div className={styles.statusRow}><p className={styles.status}>{status}</p>{loadingMore&&<LoaderCircle className={styles.spinner} size={16}/>}</div>{providers.length>0&&<div className={styles.providers}>{providers.map(provider=><span key={provider.name} className={provider.count>0?styles.providerOk:styles.providerFailed}>{provider.name}: {provider.count}</span>)}</div>}</div>
    </div></div>
    {items.length>0?<div className={styles.resultsViewport}><div className={styles.results}>{items.map(item=><button key={item.id} className={selectedId===item.id?styles.selecting:undefined} onClick={()=>void select(item)} disabled={saving||value.length>=4} title={`${item.provider}: ${item.source}`}><img src={item.previewUrl} alt="Search result" loading="lazy" decoding="async"/><span>{item.source}</span><small>{item.width}×{item.height}</small></button>)}</div></div>:<div className={styles.galleryEmpty}><ImageIcon size={28}/><span>Search results will appear here.</span></div>}
  </div>;
}
