import { api } from 'shared/api/apiClient';
import styles from './WordImageGrid.module.sass';
export function WordImageGrid({ images, alt, compact = false, square = false }: { images: string[]; alt: string; compact?: boolean; square?: boolean }) {
  const list = images.filter(Boolean).slice(0,4);
  if (!list.length) return null;
  return <div className={`${styles.grid} ${styles[`count${list.length}`]} ${compact?styles.compact:''} ${square?styles.square:''}`}>{list.map((image,index)=><img key={`${image}-${index}`} src={api.imageUrl(image)} alt={`${alt} ${index+1}`}/>)}</div>;
}
