import {
  BookOpen,
  ChevronLeft,
  ChevronRight,
  Command,
  FolderOpen,
  LayoutDashboard,
  LogOut,
  Moon,
  Play,
  Search,
  Settings2,
  Sparkles,
  Sun,
  UserRound,
  X,
} from 'lucide-react';
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { NavLink, Outlet, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from 'app/providers/AuthProvider';
import { useData } from 'app/providers/DataProvider';
import styles from './AppShell.module.sass';

const nav = [
  ['/', 'Overview', LayoutDashboard],
  ['/words', 'Dictionary', BookOpen],
  ['/folders', 'Collections', FolderOpen],
  ['/study', 'Study', Play],
] as const;

const mobileNav = [...nav, ['/account', 'Account', UserRound] as const];

type Theme = 'dark' | 'light';

export function AppShell() {
  const { user, logout } = useAuth();
  const { folders, words } = useData();
  const navigate = useNavigate();
  const location = useLocation();
  const searchInputRef = useRef<HTMLInputElement>(null);
  const [compact, setCompact] = useState(() => localStorage.getItem('vocabflow-sidebar') === 'compact');
  const [theme, setTheme] = useState<Theme>(() => localStorage.getItem('vocabflow-theme') === 'light' ? 'light' : 'dark');
  const [searchOpen, setSearchOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [studyActive, setStudyActive] = useState(false);
  const [overlayDepth, setOverlayDepth] = useState(0);
  const [mobileNavOverlayDepth, setMobileNavOverlayDepth] = useState(0);

  const normalized = query.trim().toLowerCase();
  const wordResults = useMemo(() => normalized
    ? words.filter((word) => `${word.word} ${word.translation} ${word.example}`.toLowerCase().includes(normalized)).slice(0, 6)
    : words.filter((word) => word.dueAt <= Date.now()).slice(0, 4), [normalized, words]);
  const folderResults = useMemo(() => normalized
    ? folders.filter((folder) => folder.name.toLowerCase().includes(normalized)).slice(0, 4)
    : folders.slice(0, 3), [folders, normalized]);
  const due = words.filter((word) => word.dueAt <= Date.now()).length;

  useLayoutEffect(() => {
    const updateViewportHeight = () => {
      const height = window.innerHeight;
      document.documentElement.style.setProperty('--app-viewport-height', `${Math.round(height)}px`);
    };
    updateViewportHeight();
    window.addEventListener('resize', updateViewportHeight);
    window.addEventListener('orientationchange', updateViewportHeight);
    window.visualViewport?.addEventListener('resize', updateViewportHeight);
    window.visualViewport?.addEventListener('scroll', updateViewportHeight);
    return () => {
      window.removeEventListener('resize', updateViewportHeight);
      window.removeEventListener('orientationchange', updateViewportHeight);
      window.visualViewport?.removeEventListener('resize', updateViewportHeight);
      window.visualViewport?.removeEventListener('scroll', updateViewportHeight);
    };
  }, []);

  useEffect(() => {
    document.documentElement.dataset.theme = theme;
    localStorage.setItem('vocabflow-theme', theme);
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('vocabflow-sidebar', compact ? 'compact' : 'expanded');
  }, [compact]);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') {
        event.preventDefault();
        setSearchOpen(true);
      }
      if (event.key === 'Escape') setSearchOpen(false);
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, []);

  useEffect(() => {
    const onStudyActivity = (event: Event) => {
      const detail = (event as CustomEvent<boolean>).detail;
      setStudyActive(Boolean(detail));
    };
    window.addEventListener('vocabflow-study-activity', onStudyActivity as EventListener);
    return () => window.removeEventListener('vocabflow-study-activity', onStudyActivity as EventListener);
  }, []);

  useEffect(() => {
    const onOverlayActivity = (event: Event) => {
      const delta = Number((event as CustomEvent<number>).detail) || 0;
      setOverlayDepth((value) => Math.max(0, value + delta));
    };
    window.addEventListener('vocabflow-overlay-activity', onOverlayActivity as EventListener);
    return () => window.removeEventListener('vocabflow-overlay-activity', onOverlayActivity as EventListener);
  }, []);

  useEffect(() => {
    const onMobileNavActivity = (event: Event) => {
      const delta = Number((event as CustomEvent<number>).detail) || 0;
      setMobileNavOverlayDepth((value) => Math.max(0, value + delta));
    };
    window.addEventListener('vocabflow-mobile-nav-activity', onMobileNavActivity as EventListener);
    return () => window.removeEventListener('vocabflow-mobile-nav-activity', onMobileNavActivity as EventListener);
  }, []);

  useEffect(() => {
    if (!searchOpen) return;
    setQuery('');
    window.setTimeout(() => searchInputRef.current?.focus(), 30);
  }, [searchOpen]);

  useEffect(() => {
    setSearchOpen(false);
    if (location.pathname !== '/study') setStudyActive(false);
  }, [location.pathname, location.search]);

  const go = (to: string) => {
    setSearchOpen(false);
    navigate(to);
  };

  const toggleTheme = () => setTheme((value) => value === 'dark' ? 'light' : 'dark');
  const topbarHidden = studyActive || overlayDepth > 0;

  return <div className={`${styles.app} ${compact ? styles.compact : ''}`}>
    <aside className={styles.sidebar}>
      <div className={styles.sidebarTop}>
        <button className={styles.brand} type="button" onClick={() => navigate('/')} aria-label="Open overview">
          <span className={styles.logoMark}><Sparkles size={19}/></span>
          <span className={styles.brandCopy}><strong>VocabFlow</strong><small>Personal language lab</small></span>
        </button>
        <button className={styles.collapse} type="button" onClick={() => setCompact((value) => !value)} title={compact ? 'Expand sidebar' : 'Collapse sidebar'}>
          {compact ? <ChevronRight size={17}/> : <ChevronLeft size={17}/>}<span className={styles.srOnly}>Toggle sidebar</span>
        </button>
      </div>

      <nav className={styles.nav} aria-label="Primary navigation">
        <span className={styles.navLabel}>Workspace</span>
        {nav.map(([to, label, Icon]) => <NavLink key={to} to={to} end={to === '/'} className={({ isActive }) => isActive ? styles.active : ''} title={compact ? label : undefined}>
          <span className={styles.navIcon}><Icon size={19}/></span><span className={styles.navText}>{label}</span>
        </NavLink>)}
      </nav>

      <section className={styles.reviewCard}>
        <div><Sparkles size={17}/><span>Daily review</span></div>
        <strong>{due || 'All clear'}</strong>
        <p>{due ? `${due} ${due === 1 ? 'word is' : 'words are'} ready to repeat.` : 'Nothing is overdue right now.'}</p>
        <button type="button" onClick={() => navigate('/study')}>{due ? 'Start review' : 'Practice anyway'}<Play size={15}/></button>
      </section>

      <div className={styles.sidebarFooter}>
        <NavLink to="/account" className={styles.profile} title={compact ? 'Account' : undefined}>
          <span>{user?.displayName.slice(0, 2).toUpperCase()}</span>
          <span className={styles.profileCopy}><strong>{user?.displayName}</strong><small>@{user?.username}</small></span>
          <Settings2 className={styles.profileSettings} size={17}/>
        </NavLink>
        <button className={styles.logout} onClick={() => void logout()} title="Log out"><LogOut size={18}/><span>Log out</span></button>
      </div>
    </aside>

    <div className={`${styles.workspace} ${studyActive ? styles.studyActive : ''}`}>
      {!topbarHidden && <header className={styles.topbar}>
        <button className={styles.searchButton} type="button" onClick={() => setSearchOpen(true)}>
          <Search size={18}/><span>Search words, folders, actions…</span><kbd><Command size={12}/>K</kbd>
        </button>
        <div className={styles.topActions}>
          <button className={styles.iconButton} type="button" onClick={toggleTheme} title={`Switch to ${theme === 'dark' ? 'light' : 'dark'} theme`} aria-label={`Switch to ${theme === 'dark' ? 'light' : 'dark'} theme`}>
            {theme === 'dark' ? <Sun size={18}/> : <Moon size={18}/>}
          </button>
          <button className={styles.topAvatar} type="button" onClick={() => navigate('/account')} title="Open account">{user?.displayName.slice(0, 2).toUpperCase()}</button>
        </div>
      </header>}
      <main className={`${styles.main} ${studyActive ? styles.mainStudy : ''}`}><Outlet/></main>
    </div>

    {mobileNavOverlayDepth === 0 && <div className={styles.mobileNav}>{mobileNav.map(([to, label, Icon]) => <NavLink key={to} to={to} end={to === '/'} className={({ isActive }) => isActive ? styles.active : ''}><Icon size={20}/><small>{label}</small></NavLink>)}</div>}

    {searchOpen && <div className={styles.commandBackdrop} onMouseDown={(event) => { if (event.currentTarget === event.target) setSearchOpen(false); }}>
      <section className={styles.commandPanel} role="dialog" aria-modal="true" aria-label="Global search">
        <header><Search size={20}/><input ref={searchInputRef} value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search your vocabulary…"/><kbd>ESC</kbd><button type="button" onClick={() => setSearchOpen(false)} aria-label="Close search"><X size={18}/></button></header>
        <div className={styles.commandContent}>
          <div className={styles.commandGroup}>
            <span>Quick actions</span>
            <button type="button" onClick={() => go('/study')}><span className={styles.resultIcon}><Play/></span><span><strong>Start a study session</strong><small>Review due and weak words first</small></span><em>Study</em></button>
            <button type="button" onClick={() => go('/words')}><span className={styles.resultIcon}><BookOpen/></span><span><strong>Open dictionary</strong><small>Search, edit, and import words</small></span><em>Words</em></button>
          </div>
          {folderResults.length > 0 && <div className={styles.commandGroup}>
            <span>Collections</span>
            {folderResults.map((folder) => <button key={folder.id} type="button" onClick={() => go(`/study?folder=${folder.id}`)}><span className={styles.folderIcon} style={{ background: `${folder.color}20`, color: folder.color }}>{folder.icon}</span><span><strong>{folder.name}</strong><small>{words.filter((word) => word.folderId === folder.id).length} words</small></span><em>Open</em></button>)}
          </div>}
          {wordResults.length > 0 && <div className={styles.commandGroup}>
            <span>{normalized ? 'Matching words' : 'Ready to review'}</span>
            {wordResults.map((word) => <button key={word.id} type="button" onClick={() => go(`/study?word=${word.id}`)}><span className={styles.wordIcon}>{word.word.slice(0, 1).toUpperCase()}</span><span><strong>{word.word}</strong><small>{word.translation}</small></span><em>{word.score}%</em></button>)}
          </div>}
          {normalized && wordResults.length === 0 && folderResults.length === 0 && <div className={styles.noResults}><Search/><strong>No matches found</strong><span>Try another word, translation, or collection name.</span></div>}
        </div>
        <footer><span>Search is available anywhere with Ctrl/⌘ K</span></footer>
      </section>
    </div>}
  </div>;
}
