import type { InputHTMLAttributes, SelectHTMLAttributes, TextareaHTMLAttributes } from 'react';
import styles from './FormControls.module.sass';
export function Field({ label, children, hint }: { label: string; children: React.ReactNode; hint?: string }) { return <label className={styles.field}><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
export function Input(props: InputHTMLAttributes<HTMLInputElement>) { return <input className={styles.control} {...props}/>; }
export function Select(props: SelectHTMLAttributes<HTMLSelectElement>) { return <select className={styles.control} {...props}/>; }
export function Textarea(props: TextareaHTMLAttributes<HTMLTextAreaElement>) { return <textarea className={`${styles.control} ${styles.textarea}`} {...props}/>; }
