import type { WordExampleGroup, WordSense, WordTranslationRow } from 'entities/word/model/types';
import { HighlightedText } from 'shared/ui/HighlightedText';
import { ChevronDown } from 'lucide-react';
import styles from './UsageExamples.module.sass';

function title(value: string): string {
  const labels: Record<string,string> = {
    noun: 'Noun', verb: 'Verb', adjective: 'Adjective', adverb: 'Adverb',
    preposition: 'Preposition', conjunction: 'Conjunction', pronoun: 'Pronoun',
    interjection: 'Interjection', phrase: 'Phrases', phrases: 'Phrases', examples: 'Usage examples', general: 'Usage examples',
  };
  return labels[value] || value.charAt(0).toUpperCase() + value.slice(1);
}

function BilingualRows({ rows, word }: { rows: WordTranslationRow[]; word: string }) {
  return <div className={styles.translationList}>{rows.map((row,index)=><div className={styles.translationRow} key={`${row.english}|${row.russian}|${index}`}>
    {row.english&&<span className={styles.english}><HighlightedText text={row.english} word={word}/></span>}
    {row.english&&row.russian&&<span className={styles.dash}>—</span>}
    {row.russian&&<span className={styles.russian}>{row.russian}</span>}
  </div>)}</div>;
}

function SenseList({ senses, fallbackRows, word }: { senses?: WordSense[]; fallbackRows?: WordTranslationRow[]; word: string }) {
  if (senses?.length) return <div className={styles.senseList}>{senses.map((sense,index)=><details className={styles.sense} key={`${sense.meaning}|${index}`}>
    <summary>
      <span>{sense.meaning || `Meaning ${index + 1}`}</span>
      <ChevronDown size={17}/>
    </summary>
    {!!sense.rows?.length&&<div className={styles.senseBody}><BilingualRows rows={sense.rows} word={word}/></div>}
  </details>)}</div>;
  if (fallbackRows?.length) return <BilingualRows rows={fallbackRows} word={word}/>;
  return null;
}

export function UsageExamples({ groups, word }: { groups?: WordExampleGroup[]; word: string }) {
  if (!groups?.length) return <p className={styles.empty}>No dictionary details saved for this word.</p>;
  const lexical = groups.filter(group => group.partOfSpeech !== 'phrases' && group.partOfSpeech !== 'examples' && group.partOfSpeech !== 'general');
  const phrases = groups.flatMap(group => group.phrases || (group.partOfSpeech === 'phrases' ? group.translations || [] : []));
  const examples = groups.flatMap(group => group.examples || []);
  return <div className={styles.groups}>
    {lexical.map(group => <section key={group.partOfSpeech} className={styles.section}>
      <h3>{title(group.partOfSpeech)}</h3>
      <SenseList senses={group.senses} fallbackRows={group.translations} word={word}/>
    </section>)}
    {!!phrases.length&&<section className={styles.section}>
      <h3>Phrases</h3>
      <div className={styles.phraseList}><BilingualRows rows={phrases} word={word}/></div>
    </section>}
    {!!examples.length&&<section className={styles.section}>
      <h3>Usage examples</h3>
      <div className={styles.exampleList}>{examples.map((item,index)=><article key={`${item.english}|${index}`}>
        <p><HighlightedText text={item.english} word={word}/></p>
        <small>{item.russian}</small>
      </article>)}</div>
    </section>}
  </div>;
}
