import { useState } from 'react';
import { Volume2 } from 'lucide-react';
import type { WordAudio, WordPronunciation } from 'entities/word/model/types';
import { api } from 'shared/api/apiClient';
import { formatTranscription } from 'shared/lib/transcription';
import styles from './PronunciationList.module.sass';
export function PronunciationList({ word, transcription, audio }: { word:string; transcription?:WordPronunciation; audio?:WordAudio }) {
  const [playing,setPlaying]=useState(false);
  async function play(url:string|undefined,locale:'en-US'|'en-GB'){if(!url||playing)return;setPlaying(true);try{await api.playPronunciation(url,word,locale)}finally{setPlaying(false)}}
  const rows=[{key:'american',label:'am.',locale:'en-US' as const},{key:'british',label:'br.',locale:'en-GB' as const}];
  return <div className={styles.root}>{rows.map(row=>{const value=transcription?.[row.key as keyof WordPronunciation]||'';const url=audio?.[row.key as keyof WordAudio]||'';if(!value&&!url)return null;return <div key={row.key}><b>{row.label}</b><span>{formatTranscription(value)}</span><button type="button" disabled={!url||playing} onClick={()=>void play(url,row.locale)}><Volume2 size={16}/></button></div>})}</div>;
}
