import { useEffect, type PropsWithChildren, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { X } from 'lucide-react';
import { Button } from 'shared/ui/Button';
import styles from './Modal.module.sass';

interface Props {
  title: string;
  onClose: () => void;
  wide?: boolean;
  workspace?: boolean;
  actions?: ReactNode;
}

export function Modal({ title, onClose, wide, workspace, actions, children }: PropsWithChildren<Props>) {
  const className = [styles.modal, wide ? styles.wide : '', workspace ? styles.workspace : '']
    .filter(Boolean)
    .join(' ');

  useEffect(() => {
    window.dispatchEvent(new CustomEvent('vocabflow-overlay-activity', { detail: 1 }));
    window.dispatchEvent(new CustomEvent('vocabflow-mobile-nav-activity', { detail: 1 }));
    return () => {
      window.dispatchEvent(new CustomEvent('vocabflow-overlay-activity', { detail: -1 }));
      window.dispatchEvent(new CustomEvent('vocabflow-mobile-nav-activity', { detail: -1 }));
    };
  }, []);

  const content = (
    <div
      className={styles.backdrop}
      onMouseDown={(event) => event.currentTarget === event.target && onClose()}
    >
      <section className={className}>
        <header>
          <h2>{title}</h2>
          <div className={styles.headerActions}>
            {actions}
            <Button variant="ghost" onClick={onClose} aria-label="Close"><X size={20} /></Button>
          </div>
        </header>
        <div className={styles.bodyViewport}><div className={styles.body}>{children}</div></div>
      </section>
    </div>
  );

  // Render outside AppShell/.main. Mobile Safari can clip fixed descendants of
  // overflow-scrolling containers, which previously left a ~64px uncovered strip
  // at the bottom whenever the top search bar was hidden.
  return createPortal(content, document.body);
}
