import { useCallback, useEffect, useMemo, useState, type PropsWithChildren } from 'react';
import type { Folder } from 'entities/folder/model/types';
import type { Settings } from 'entities/settings/model/types';
import type { StudySession } from 'entities/session/model/types';
import type { Word } from 'entities/word/model/types';
import { api } from 'shared/api/apiClient';
import { useAuth } from 'app/providers/AuthProvider';
import { DataContext } from '../model/DataContext';
export function DataProvider({ children }: PropsWithChildren) {
  const { user } = useAuth();
  const [folders,setFolders]=useState<Folder[]>([]); const [words,setWords]=useState<Word[]>([]); const [sessions,setSessions]=useState<StudySession[]>([]); const [settings,setSettings]=useState<Settings|null>(null); const [loading,setLoading]=useState(false);
  const reload=useCallback(async()=>{ if(!user)return; setLoading(true); try{const b=await api.bootstrap();setFolders(b.folders);setWords(b.words);setSessions(b.sessions);setSettings(b.settings);}finally{setLoading(false)} },[user]);
  useEffect(()=>{ if(user)void reload(); else {setFolders([]);setWords([]);setSessions([]);setSettings(null);} },[user,reload]);
  useEffect(()=>{document.documentElement.style.setProperty('--example-highlight',settings?.exampleHighlightColor||'#ff6b7a');},[settings?.exampleHighlightColor]);
  const value=useMemo(()=>({folders,words,sessions,settings,loading,reload,
    createFolder:async(data:Pick<Folder,'name'|'icon'|'color'>)=>{const item=await api.createFolder(data);setFolders(v=>[...v,item]);},
    updateFolder:async(id:string,data:Partial<Folder>)=>{const item=await api.updateFolder(id,data);setFolders(v=>v.map(x=>x.id===id?item:x));},
    deleteFolder:async(id:string)=>{await api.deleteFolder(id);setFolders(v=>v.filter(x=>x.id!==id));setWords(v=>v.filter(x=>x.folderId!==id));},
    exportFolder:async(id:string)=>api.exportFolder(id),
    importFolderShare:async(payload:unknown)=>{const result=await api.importFolderShare(payload);await reload();return result;},
    importQuizletPage:async(file:File)=>{const result=await api.importQuizletPage(file);await reload();return result;},
    createWord:async(data:Partial<Word>)=>{const item=await api.createWord(data);setWords(v=>[item,...v]);},
    updateWord:async(id:string,data:Partial<Word>)=>{const item=await api.updateWord(id,data);setWords(v=>v.map(x=>x.id===id?item:x));},
    deleteWord:async(id:string)=>{await api.deleteWord(id);setWords(v=>v.filter(x=>x.id!==id));},
    importWords:async(folderId:string,items:Array<Partial<Word>>)=>{const result=await api.importWords(folderId,items);await reload();return result.imported;},
    saveSettings:async(next:Settings)=>{const result=await api.updateSettings(next);setSettings(result);}
  }),[folders,words,sessions,settings,loading,reload]);
  return <DataContext.Provider value={value}>{children}</DataContext.Provider>;
}
