export function cleanTranscription(value: string): string {
  return value
    .replace(/(?:амер\.?|брит\.?|amer(?:ican)?\.?|brit(?:ish)?\.?|us|uk)\s*/gi, '')
    .replace(/[|/\\]/g, '')
    .trim();
}
export function formatTranscription(value?: string): string {
  const clean = cleanTranscription(value || '');
  return clean ? `|${clean}|` : '';
}
