import { ArrowLeft, Download, Edit3, FileCode2, FileUp, FolderPlus, Play, Search, Trash2 } from 'lucide-react';
import { useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useData } from 'app/providers/DataProvider';
import type { Folder } from 'entities/folder/model/types';
import type { Word } from 'entities/word/model/types';
import { FolderEditor } from 'features/folder-editor';
import { WordEditor } from 'features/word-editor';
import { WordDetailsModal } from 'features/word-details';
import { Button } from 'shared/ui/Button';
import { Input } from 'shared/ui/Form';
import { WordTable } from 'shared/ui/WordTable';
import { PageHeader } from 'widgets/PageHeader';
import styles from './FoldersPage.module.sass';

function safeDownloadName(value: string): string {
  return value.replace(/[^a-zA-Z0-9-_]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 70) || 'vocabflow-folder';
}

export function FoldersPage() {
  const { folders, words, deleteFolder, exportFolder, importFolderShare, importQuizletPage } = useData();
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<Folder | undefined>();
  const [busyFolderId, setBusyFolderId] = useState<string | null>(null);
  const [importing, setImporting] = useState(false);
  const [importingQuizlet, setImportingQuizlet] = useState(false);
  const [selectedFolderId, setSelectedFolderId] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const [viewing, setViewing] = useState<Word | undefined>();
  const [addingWord, setAddingWord] = useState(false);
  const [editingWord, setEditingWord] = useState<Word | undefined>();
  const fileInput = useRef<HTMLInputElement>(null);
  const quizletFileInput = useRef<HTMLInputElement>(null);

  const selectedFolder = folders.find((folder) => folder.id === selectedFolderId);
  const selectedWords = useMemo(() => words.filter((word) => word.folderId === selectedFolderId && `${word.word} ${word.translation} ${word.example}`.toLowerCase().includes(query.toLowerCase())), [words, selectedFolderId, query]);

  const handleExport = async (folder: Folder) => {
    setBusyFolderId(folder.id);
    try {
      const blob = await exportFolder(folder.id);
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `${safeDownloadName(folder.name)}.vocabflow.json`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Could not share the folder.');
    } finally {
      setBusyFolderId(null);
    }
  };

  const handleImport = async (file?: File) => {
    if (!file) return;
    setImporting(true);
    try {
      const result = await importFolderShare(file);
      const imageNote = result.missingImages ? ` ${result.missingImages} image(s) could not be imported.` : '';
      const warningNote = result.warnings.length ? `\n\nWarnings: ${result.warnings.slice(0, 5).join('\n')}${result.warnings.length > 5 ? '\n…' : ''}` : '';
      alert(`Imported “${result.folder.name}”: ${result.importedWords} words; ${result.enrichedWords} enriched from WooordHunt; ${result.linkedImages} linked and ${result.downloadedImages} downloaded images.${imageNote}${warningNote}`);
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Could not import the shared folder.');
    } finally {
      setImporting(false);
      if (fileInput.current) fileInput.current.value = '';
    }
  };

  const handleQuizletImport = async (file?: File) => {
    if (!file) return;
    setImportingQuizlet(true);
    try {
      const result = await importQuizletPage(file);
      const imageNote = result.missingImages ? ` ${result.missingImages} image(s) could not be imported.` : '';
      const warningNote = result.warnings.length ? `\n\nWarnings: ${result.warnings.slice(0, 5).join('\n')}${result.warnings.length > 5 ? '\n…' : ''}` : '';
      alert(`Imported “${result.folder.name}” from Quizlet HTML: ${result.importedWords} words; ${result.enrichedWords} enriched from WooordHunt; ${result.downloadedImages} images downloaded.${imageNote}${warningNote}`);
    } catch (error) {
      alert(error instanceof Error ? error.message : 'Could not import the saved Quizlet page.');
    } finally {
      setImportingQuizlet(false);
      if (quizletFileInput.current) quizletFileInput.current.value = '';
    }
  };

  if (selectedFolder) return <>
    <PageHeader title={selectedFolder.name} subtitle={`${selectedWords.length} words in this folder.`} actions={<div className={styles.headerActions}><Button onClick={() => { setSelectedFolderId(null); setQuery(''); }}><ArrowLeft size={17}/>Back to folders</Button><Button onClick={() => setAddingWord(true)}><FolderPlus size={17}/>Add word</Button><Button variant="primary" onClick={() => navigate(`/study?folder=${selectedFolder.id}`)}><Play size={17}/>Study folder</Button></div>}/>
    <section className={styles.folderWords}><div className={styles.folderToolbar}><Search size={17}/><Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search inside this folder…"/></div><WordTable words={selectedWords} folders={folders} onOpen={setViewing}/></section>
    {addingWord && <WordEditor initialFolderId={selectedFolder.id} onClose={() => setAddingWord(false)}/>} 
    {editingWord && <WordEditor word={editingWord} onClose={() => setEditingWord(undefined)}/>}
    {viewing && <WordDetailsModal word={viewing} onClose={() => setViewing(undefined)} onEdit={() => { setEditingWord(viewing); setViewing(undefined); }}/>} 
  </>;

  return <>
    <PageHeader title="Folders" subtitle="Organize words into meaningful topics. Click a folder to inspect its words." actions={<div className={styles.headerActions}><input ref={fileInput} className={styles.hiddenInput} type="file" accept=".json,.vocabflow.json,.zip,.vocabflow.zip,application/json,application/zip" onChange={(event) => void handleImport(event.target.files?.[0])}/><input ref={quizletFileInput} className={styles.hiddenInput} type="file" accept=".html,.htm,.mhtml,.mht,text/html,multipart/related" onChange={(event) => void handleQuizletImport(event.target.files?.[0])}/><Button onClick={() => fileInput.current?.click()} disabled={importing || importingQuizlet}><FileUp size={17}/>{importing ? 'Importing…' : 'Import'}</Button><Button onClick={() => quizletFileInput.current?.click()} disabled={importing || importingQuizlet}><FileCode2 size={17}/>{importingQuizlet ? 'Importing Quizlet…' : 'Quizlet HTML'}</Button><Button variant="primary" onClick={() => { setEditing(undefined); setOpen(true); }}><FolderPlus size={17}/>New folder</Button></div>}/>
    <div className={styles.grid}>{folders.map((folder) => {
      const list = words.filter((word) => word.folderId === folder.id);
      const known = list.filter((word) => word.score >= 75).length;
      const percent = list.length ? Math.round(known / list.length * 100) : 0;
      return <article key={folder.id} onClick={() => setSelectedFolderId(folder.id)}>
        <span style={{ background: `${folder.color}22` }}>{folder.icon}</span><h2>{folder.name}</h2><p>{list.length} words · {list.filter((word) => word.dueAt <= Date.now()).length} due</p><div className={styles.progress}><i style={{ width: `${percent}%` }}/></div><small>{percent}% known</small>
        <footer onClick={(event) => event.stopPropagation()}><Button onClick={() => navigate(`/study?folder=${folder.id}`)}><Play size={15}/>Study</Button><button title="Share with another user" disabled={busyFolderId === folder.id} onClick={() => void handleExport(folder)}><Download/></button><button title="Edit folder" onClick={() => { setEditing(folder); setOpen(true); }}><Edit3/></button><button title="Delete folder" onClick={() => confirm(`Delete “${folder.name}” and all its words?`) && void deleteFolder(folder.id)}><Trash2/></button></footer>
      </article>;
    })}</div>
    {open && <FolderEditor folder={editing} onClose={() => setOpen(false)}/>} 
  </>;
}
