import type { Folder } from 'entities/folder/model/types';
import type { Settings } from 'entities/settings/model/types';
import type { StudySession } from 'entities/session/model/types';
import type {
  ActiveStudySession,
  ActiveStudySessionSave,
  ActiveStudySessionSummary,
  StudyAnswerRequest,
  StudyCard,
} from 'entities/study/model/types';
import type { User } from 'entities/user/model/types';
import type { Word } from 'entities/word/model/types';
import type { AuthResponse, Bootstrap, ImageSearchResponse, StudyQueueRequest, TranslationLookupResponse } from './types';

const TOKEN_KEY = 'vocabflow.auth.token';
const DEFAULT_TIMEOUT_MS = 20_000;

const API_BASE_URL = (__API_BASE_URL__ || '').replace(/\/+$/, '');

function backendUrl(value: string): string {
  if (!value) return API_BASE_URL || '';
  if (/^https?:\/\//i.test(value) || value.startsWith('tts://') || value.startsWith('blob:') || value.startsWith('data:')) return value;
  const path = value.startsWith('/') ? value : `/${value}`;
  return `${API_BASE_URL}${path}`;
}

export const authToken = {
  get: () => localStorage.getItem(TOKEN_KEY),
  set: (token: string) => localStorage.setItem(TOKEN_KEY, token),
  clear: () => localStorage.removeItem(TOKEN_KEY),
};

interface RequestOptions { timeoutMs?: number; }

async function request<T>(url: string, init: RequestInit = {}, options: RequestOptions = {}): Promise<T> {
  const token = authToken.get();
  const controller = new AbortController();
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  let timedOut = false;

  const forwardAbort = () => controller.abort(init.signal?.reason);
  if (init.signal?.aborted) forwardAbort();
  else init.signal?.addEventListener('abort', forwardAbort, { once: true });

  const timeout = window.setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, timeoutMs);

  try {
    const response = await fetch(backendUrl(url), {
      ...init,
      signal: controller.signal,
      headers: {
        ...(init.body instanceof FormData ? {} : { 'content-type': 'application/json' }),
        ...(token ? { authorization: `Bearer ${token}` } : {}),
        ...init.headers,
      },
    });

    if (!response.ok) {
      const payload = await response.json().catch(() => ({ error: response.statusText }));
      if (response.status === 401) authToken.clear();
      throw new Error(payload.error || response.statusText || `Request failed with HTTP ${response.status}.`);
    }
    if (response.status === 204) return undefined as T;
    return response.json() as Promise<T>;
  } catch (error) {
    if (timedOut) throw new Error('The server took too long to respond. Check your connection and try again.');
    if (error instanceof DOMException && error.name === 'AbortError') throw new Error('The request was cancelled.');
    throw error;
  } finally {
    window.clearTimeout(timeout);
    init.signal?.removeEventListener('abort', forwardAbort);
  }
}

async function downloadRequest(url: string): Promise<Blob> {
  const token = authToken.get();
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), 45_000);
  try {
    const response = await fetch(backendUrl(url), {
      signal: controller.signal,
      headers: token ? { authorization: `Bearer ${token}` } : {},
    });
    if (!response.ok) {
      const payload = await response.json().catch(() => ({ error: response.statusText }));
      throw new Error(payload.error || response.statusText);
    }
    return response.blob();
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') throw new Error('The download timed out. Try again.');
    throw error;
  } finally {
    window.clearTimeout(timeout);
  }
}

async function getSpeechVoices(): Promise<SpeechSynthesisVoice[]> {
  if (!('speechSynthesis' in window)) return [];
  const immediate = window.speechSynthesis.getVoices();
  if (immediate.length) return immediate;
  return new Promise((resolve) => {
    const timeout = window.setTimeout(() => resolve(window.speechSynthesis.getVoices()), 800);
    window.speechSynthesis.addEventListener('voiceschanged', () => {
      window.clearTimeout(timeout);
      resolve(window.speechSynthesis.getVoices());
    }, { once: true });
  });
}

async function playSystemSpeech(text: string, locale: string): Promise<void> {
  if (!text || !('speechSynthesis' in window)) throw new Error('Pronunciation is unavailable on this device.');
  window.speechSynthesis.cancel();
  const voices = await getSpeechVoices();
  const normalized = locale.toLowerCase();
  const exact = voices.filter((item) => item.lang.toLowerCase() === normalized);
  const voice = exact.find((item) => item.localService)
    || exact[0]
    || voices.find((item) => item.lang.toLowerCase().startsWith(normalized.split('-')[0]) && item.localService)
    || voices.find((item) => item.lang.toLowerCase().startsWith(normalized.split('-')[0]));

  await new Promise<void>((resolve, reject) => {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = locale;
    if (voice) utterance.voice = voice;
    utterance.rate = 0.88;
    utterance.onend = () => resolve();
    utterance.onerror = () => reject(new Error('Could not play pronunciation.'));
    window.speechSynthesis.speak(utterance);
  });
}

async function playAudioRequest(url: string, fallbackText = '', locale = 'en-US'): Promise<void> {
  if (url.startsWith('tts://')) {
    const parsed = new URL(url);
    const text = decodeURIComponent(parsed.pathname.replace(/^\//, '')) || fallbackText;
    const requestedLocale = parsed.hostname
      ? parsed.hostname.replace(/^en-us$/i, 'en-US').replace(/^en-gb$/i, 'en-GB')
      : locale;
    await playSystemSpeech(text, requestedLocale);
    return;
  }

  const token = authToken.get();
  const audioRequestUrl = url.startsWith('/audio-cache/')
    ? backendUrl(url)
    : backendUrl(`/api/translations/audio?url=${encodeURIComponent(url)}`);
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), 15_000);

  try {
    const response = await fetch(audioRequestUrl, {
      signal: controller.signal,
      headers: url.startsWith('/audio-cache/') ? {} : (token ? { authorization: `Bearer ${token}` } : {}),
    });
    if (!response.ok) throw new Error(`Audio source returned HTTP ${response.status}.`);
    const blob = await response.blob();
    const objectUrl = URL.createObjectURL(blob);
    const audio = new Audio(objectUrl);
    await new Promise<void>((resolve, reject) => {
      audio.addEventListener('ended', () => { URL.revokeObjectURL(objectUrl); resolve(); }, { once: true });
      audio.addEventListener('error', () => { URL.revokeObjectURL(objectUrl); reject(new Error('Could not play pronunciation.')); }, { once: true });
      void audio.play().catch((error) => { URL.revokeObjectURL(objectUrl); reject(error); });
    });
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') throw new Error('Pronunciation request timed out.');
    throw error;
  } finally {
    window.clearTimeout(timeout);
  }
}

export const api = {
  register: (body: { username: string; displayName: string; password: string }) => request<AuthResponse>('/api/auth/register', { method: 'POST', body: JSON.stringify(body) }),
  login: (body: { username: string; password: string }) => request<AuthResponse>('/api/auth/login', { method: 'POST', body: JSON.stringify(body) }),
  me: () => request<{ user: User }>('/api/auth/me'),
  logout: () => request<void>('/api/auth/logout', { method: 'POST' }),
  changePassword: (body: { currentPassword: string; newPassword: string }) => request<void>('/api/auth/password', { method: 'PUT', body: JSON.stringify(body) }),
  bootstrap: () => request<Bootstrap>('/api/meta/bootstrap'),
  updateSettings: (body: Settings) => request<Settings>('/api/meta/settings', { method: 'PUT', body: JSON.stringify(body) }),
  createFolder: (body: Pick<Folder, 'name' | 'icon' | 'color'>) => request<Folder>('/api/folders', { method: 'POST', body: JSON.stringify(body) }),
  updateFolder: (id: string, body: Partial<Folder>) => request<Folder>(`/api/folders/${id}`, { method: 'PUT', body: JSON.stringify(body) }),
  deleteFolder: (id: string) => request<void>(`/api/folders/${id}`, { method: 'DELETE' }),
  exportFolder: (id: string) => downloadRequest(`/api/folders/packages/${id}/export`),
  importFolderShare: (payload: unknown | File) => {
    const body = payload instanceof File ? (() => { const form = new FormData(); form.append('file', payload); return form; })() : JSON.stringify(payload);
    return request<{ folder: Folder; importedWords: number; linkedImages: number; downloadedImages: number; bundledImages?: number; missingImages: number; enrichedWords: number; warnings: string[] }>('/api/folders/packages/import', { method: 'POST', body }, { timeoutMs: 120_000 });
  },
  importQuizletPage: (file: File) => {
    const form = new FormData();
    form.append('page', file);
    return request<{ folder: Folder; importedWords: number; linkedImages: number; downloadedImages: number; missingImages: number; enrichedWords: number; warnings: string[] }>('/api/folders/packages/quizlet-page', { method: 'POST', body: form }, { timeoutMs: 120_000 });
  },
  createWord: (body: Partial<Word>) => request<Word>('/api/words', { method: 'POST', body: JSON.stringify(body) }),
  updateWord: (id: string, body: Partial<Word>) => request<Word>(`/api/words/${id}`, { method: 'PUT', body: JSON.stringify(body) }),
  deleteWord: (id: string) => request<void>(`/api/words/${id}`, { method: 'DELETE' }),
  importWords: (folderId: string, items: Array<Partial<Word>>) => request<{ imported: number }>('/api/words/import', { method: 'POST', body: JSON.stringify({ folderId, items }) }, { timeoutMs: 120_000 }),
  studyQueue: ({ folderId, wordId, mode }: StudyQueueRequest) => {
    const params = new URLSearchParams({ mode });
    if (folderId) params.set('folderId', folderId);
    if (wordId) params.set('wordId', wordId);
    return request<StudyCard[]>(`/api/study/queue?${params}`, {}, { timeoutMs: 25_000 });
  },
  answer: (body: StudyAnswerRequest) => request<{ word: Word; active: ActiveStudySessionSummary; duplicate: boolean }>('/api/study/answer', { method: 'POST', body: JSON.stringify(body) }, { timeoutMs: 12_000 }),
  getActiveStudySession: () => request<ActiveStudySession | null>('/api/study/active', {}, { timeoutMs: 20_000 }),
  getActiveStudySessionSummary: () => request<ActiveStudySessionSummary | null>('/api/study/active/summary', {}, { timeoutMs: 10_000 }),
  saveActiveStudySession: (body: ActiveStudySessionSave, keepalive = false) => request<ActiveStudySession>('/api/study/active', { method: 'PUT', body: JSON.stringify(body), keepalive }, { timeoutMs: 12_000 }),
  clearActiveStudySession: () => request<void>('/api/study/active', { method: 'DELETE' }, { timeoutMs: 12_000 }),
  saveSession: (sessionId: string) => request<StudySession | undefined>('/api/study/session', { method: 'POST', body: JSON.stringify({ sessionId }) }, { timeoutMs: 15_000 }),
  lookupTranslation: (word: string) => request<TranslationLookupResponse>(`/api/translations/wooordhunt?word=${encodeURIComponent(word)}`, {}, { timeoutMs: 45_000 }),
  playPronunciation: (url: string, fallbackText = '', locale = 'en-US') => playAudioRequest(url, fallbackText, locale),
  searchImages: (query: string) => request<ImageSearchResponse>(`/api/images/search?q=${encodeURIComponent(query)}&limit=50`, {}, { timeoutMs: 60_000 }),
  imageSearchProgress: (searchId: string) => request<ImageSearchResponse>(`/api/images/search/${encodeURIComponent(searchId)}`, {}, { timeoutMs: 30_000 }),
  saveRemoteImage: (id: string) => request<{ url: string }>('/api/images/save', { method: 'POST', body: JSON.stringify({ id }) }, { timeoutMs: 60_000 }),
  uploadImage: async (file: File) => {
    const form = new FormData();
    form.append('image', file);
    return request<{ url: string }>('/api/images/upload', { method: 'POST', body: form }, { timeoutMs: 60_000 });
  },
  imageUrl: (value: string) => value.startsWith('http') ? backendUrl(`/api/images/proxy?url=${encodeURIComponent(value)}`) : backendUrl(value),
};
