import { useEffect, useMemo, useState, type PropsWithChildren } from 'react';
import type { User } from 'entities/user/model/types';
import { api, authToken } from 'shared/api/apiClient';
import { AuthContext } from '../model/AuthContext';
export function AuthProvider({ children }: PropsWithChildren) {
  const [user, setUser] = useState<User | null>(null);
  const [initializing, setInitializing] = useState(true);
  useEffect(() => { (async () => { if (!authToken.get()) return setInitializing(false); try { const result = await api.me(); setUser(result.user); } catch { authToken.clear(); } finally { setInitializing(false); } })(); }, []);
  const value = useMemo(() => ({ user, initializing,
    login: async (username: string, password: string) => { const result = await api.login({ username, password }); authToken.set(result.token); setUser(result.user); },
    register: async (username: string, displayName: string, password: string) => { const result = await api.register({ username, displayName, password }); authToken.set(result.token); setUser(result.user); },
    logout: async () => { try { await api.logout(); } finally { authToken.clear(); setUser(null); } },
    changePassword: async (currentPassword: string, newPassword: string) => { await api.changePassword({ currentPassword, newPassword }); }
  }), [user, initializing]);
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}
