import styles from './HighlightedText.module.sass';
export function HighlightedText({ text, word }: { text: string; word: string }) {
  const normalized = word.trim();
  if (!normalized) return <>{text}</>;
  const escaped = normalized.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const parts = text.split(new RegExp(`(${escaped})`, 'ig'));
  return <>{parts.map((part,index)=>part.toLowerCase()===normalized.toLowerCase()?<strong className={styles.highlight} key={index}>{part}</strong>:<span key={index}>{part}</span>)}</>;
}
