import { BarChart3 } from 'lucide-react';
import styles from './FrequencyBadge.module.sass';

export function FrequencyBadge({ rank, compact=false }: { rank?: number | null; compact?: boolean }) {
  if (!Number.isSafeInteger(rank) || Number(rank) <= 0) return null;
  return <span className={`${styles.badge} ${compact ? styles.compact : ''}`} title="WooordHunt frequency rank: a lower number means a more common word"><BarChart3 size={compact?12:14}/><span>#{Number(rank).toLocaleString('en-US')}</span></span>;
}
