import type { Folder } from 'entities/folder/model/types';
import type { Word } from 'entities/word/model/types';
import { api } from 'shared/api/apiClient';
import { FrequencyBadge } from 'shared/ui/FrequencyBadge';
import { formatSeconds, knowledgeLabel, scoreTone } from 'shared/lib/format';
import styles from './WordTable.module.sass';

export function WordTable({ words, folders, onOpen }: { words: Word[]; folders: Folder[]; onOpen: (word: Word) => void }) {
  return <div className={styles.table}>{words.map(word => {
    const images = word.images?.length ? word.images : word.image ? [word.image] : [];
    const folderName = folders.find(folder => folder.id === word.folderId)?.name || 'Unknown';
    return <article key={word.id} role="button" tabIndex={0} onClick={() => onOpen(word)} onKeyDown={event => { if (event.key === 'Enter' || event.key === ' ') onOpen(word); }}>
      <div className={styles.word}>{images[0] ? <img src={api.imageUrl(images[0])} alt=""/> : <span>{word.word[0]?.toUpperCase()}</span>}<div><div className={styles.wordTitle}><strong>{word.word}</strong><FrequencyBadge rank={word.frequencyRank} compact/></div><small>{word.translation}</small></div></div>
      <em className={styles.folder}>{folderName}</em>
      <div className={styles.meta}>
        <b className={styles[scoreTone(word.score)]}>{word.score}% · {knowledgeLabel(word.score)}</b>
        <span>{formatSeconds(word.lastTime)}</span>
      </div>
    </article>;
  })}</div>;
}
