import { FormEvent, useEffect, useRef, useState } from 'react';
import { AlertTriangle, ChevronDown, Heart, ImageOff, Pause, RefreshCw, Volume2 } from 'lucide-react';
import type { Settings } from 'entities/settings/model/types';
import type {
  ActiveStudySession,
  ActiveStudySessionSave,
  StudyCard,
  StudyMode,
  StudySessionAnswer,
} from 'entities/study/model/types';
import { api } from 'shared/api/apiClient';
import { Button } from 'shared/ui/Button';
import { FrequencyBadge } from 'shared/ui/FrequencyBadge';
import { HighlightedText } from 'shared/ui/HighlightedText';
import { PronunciationList } from 'shared/ui/PronunciationList';
import { UsageExamples } from 'shared/ui/UsageExamples';
import { WordImageGrid } from 'shared/ui/WordImageGrid';
import styles from './StudySessionView.module.sass';

interface Props {
  cards: StudyCard[];
  settings: Settings;
  folderId: string | null;
  mode: StudyMode;
  initial: ActiveStudySession;
  onFinish: () => void;
  onPause: (state: ActiveStudySession) => void;
  onWordUpdated: () => Promise<void>;
}

type Phase = 'idle' | 'submitting' | 'feedback' | 'error' | 'finishing';

interface PendingAnswer {
  answerId: string;
  correct: boolean;
  seconds: number;
  attempts: number;
  optionIndex: number | null;
  result: StudySessionAnswer;
}

function createAnswerId() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
  return `answer-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
}

export function StudySessionView({ cards, settings, folderId, mode, initial, onFinish, onPause, onWordUpdated }: Props) {
  const [index, setIndex] = useState(initial.index || 0);
  const [elapsed, setElapsed] = useState(initial.elapsed || 0);
  const [answered, setAnswered] = useState<number | null | undefined>(undefined);
  const [correctCount, setCorrectCount] = useState(initial.correctCount || 0);
  const [times, setTimes] = useState<number[]>(initial.times || []);
  const [answers, setAnswers] = useState<StudySessionAnswer[]>(initial.answers || []);
  const [feedback, setFeedback] = useState<{ correct: boolean; correctAnswer: string; selectedAnswer: string } | null>(null);
  const [examplesOpen, setExamplesOpen] = useState(false);
  const [lives, setLives] = useState(3);
  const [typed, setTyped] = useState('');
  const [typingMessage, setTypingMessage] = useState('');
  const [phase, setPhase] = useState<Phase>('idle');
  const [syncError, setSyncError] = useState('');
  const [keyboardOpen, setKeyboardOpen] = useState(false);
  const typingInput = useRef<HTMLInputElement>(null);

  const started = useRef(performance.now() - (initial.elapsed || 0) * 1000);
  const firstCard = useRef(true);
  const leaving = useRef(false);
  const pendingAnswer = useRef<PendingAnswer | null>(null);
  const transitionTimer = useRef<number | null>(null);
  const stateRef = useRef({
    index: initial.index || 0,
    correctCount: initial.correctCount || 0,
    times: initial.times || [],
    answers: initial.answers || [],
    elapsed: initial.elapsed || 0,
  });

  const card = cards[index];
  stateRef.current = { index, correctCount, times, answers, elapsed };

  useEffect(() => {
    const carry = firstCard.current ? (initial.elapsed || 0) : 0;
    firstCard.current = false;
    started.current = performance.now() - carry * 1000;
    setElapsed(carry);
    setAnswered(undefined);
    setExamplesOpen(false);
    setLives(3);
    setTyped('');
    setTypingMessage('');
    setFeedback(null);
    setSyncError('');
    setPhase('idle');
    pendingAnswer.current = null;

    const timer = window.setInterval(() => setElapsed((performance.now() - started.current) / 1000), 100);
    return () => window.clearInterval(timer);
  }, [index, initial.elapsed]);

  useEffect(() => () => {
    if (transitionTimer.current !== null) window.clearTimeout(transitionTimer.current);
  }, []);

  useEffect(() => {
    if (mode !== 'typing-russian-to-english' || !window.visualViewport) return;
    const viewport = window.visualViewport;
    const updateKeyboard = () => {
      const open = viewport.height < window.innerHeight * 0.76;
      setKeyboardOpen(open);
      document.documentElement.style.setProperty('--study-visual-height', `${Math.round(viewport.height)}px`);
    };
    updateKeyboard();
    viewport.addEventListener('resize', updateKeyboard);
    return () => {
      viewport.removeEventListener('resize', updateKeyboard);
      setKeyboardOpen(false);
      document.documentElement.style.removeProperty('--study-visual-height');
    };
  }, [mode]);

  const audioUrl = card?.audio?.american || card?.audio?.british || '';
  async function playAudio() {
    if (!audioUrl || !card) return;
    await api.playPronunciation(audioUrl, card.word, 'en-US');
  }

  useEffect(() => {
    if (!card) return;
    if (mode === 'audio-to-russian' || mode === 'audio-to-image') {
      void playAudio().catch(() => undefined);
    } else if (settings.autoSpeak && card.prompt && mode !== 'image-to-english' && mode !== 'typing-russian-to-english' && 'speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(card.prompt);
      utterance.lang = mode === 'russian-to-english' ? 'ru-RU' : 'en-US';
      window.speechSynthesis.speak(utterance);
    }
  }, [card, mode, settings.autoSpeak]);

  function snapshot(): ActiveStudySessionSave {
    const current = stateRef.current;
    return {
      sessionId: initial.sessionId,
      wordIds: initial.wordIds.length ? initial.wordIds : cards.map((item) => item.wordId),
      index: current.index,
      correctCount: current.correctCount,
      times: current.times,
      answers: current.answers,
      folderId,
      mode,
      elapsed: current.elapsed,
      processedAnswerIds: initial.processedAnswerIds || [],
    };
  }

  async function persist(keepalive = false) {
    return api.saveActiveStudySession(snapshot(), keepalive);
  }

  useEffect(() => {
    window.dispatchEvent(new CustomEvent('vocabflow-study-activity', { detail: true }));
    return () => { window.dispatchEvent(new CustomEvent('vocabflow-study-activity', { detail: false })); };
  }, []);

  useEffect(() => {
    const onHidden = () => {
      if (document.hidden && !leaving.current) void persist(true).catch(() => undefined);
    };
    const onPageHide = () => {
      if (!leaving.current) void persist(true).catch(() => undefined);
    };
    document.addEventListener('visibilitychange', onHidden);
    window.addEventListener('pagehide', onPageHide);
    return () => {
      document.removeEventListener('visibilitychange', onHidden);
      window.removeEventListener('pagehide', onPageHide);
      if (!leaving.current) void persist(true).catch(() => undefined);
    };
  }, []);

  async function pause() {
    if (phase === 'submitting' || phase === 'finishing') return;
    let saved: ActiveStudySession;
    try {
      saved = await persist();
    } catch {
      const data = snapshot();
      saved = {
        ...data,
        cards,
        processedAnswerIds: data.processedAnswerIds || [],
        pausedAt: Date.now(),
        updatedAt: Date.now(),
      };
    }
    leaving.current = true;
    onPause(saved);
  }

  async function finish() {
    if (phase === 'finishing' || phase === 'submitting') return;
    setPhase('finishing');
    setSyncError('');
    try {
      await api.saveSession(initial.sessionId);
      leaving.current = true;
      onFinish();
      void onWordUpdated().catch(() => undefined);
    } catch (caught) {
      setSyncError(caught instanceof Error ? caught.message : 'Could not finish the session.');
      setPhase('error');
    }
  }

  async function submitPending() {
    const pending = pendingAnswer.current;
    if (!pending || !card) return;
    setPhase('submitting');
    setSyncError('');

    try {
      await api.answer({
        sessionId: initial.sessionId,
        answerId: pending.answerId,
        wordId: card.wordId,
        correct: pending.correct,
        seconds: pending.seconds,
        attempts: pending.attempts,
        result: pending.result,
      });

      const nextAnswers = [...stateRef.current.answers, pending.result];
      const nextCorrect = stateRef.current.correctCount + (pending.correct ? 1 : 0);
      const nextTimes = [...stateRef.current.times, pending.seconds];
      const nextIndex = index + 1;

      setAnswered(pending.optionIndex);
      setCorrectCount(nextCorrect);
      setTimes(nextTimes);
      setAnswers(nextAnswers);
      setFeedback({
        correct: pending.correct,
        correctAnswer: pending.result.correctAnswer,
        selectedAnswer: pending.result.selectedAnswer,
      });
      setPhase('feedback');
      pendingAnswer.current = null;

      const delay = pending.correct ? settings.correctAnswerDelayMs : settings.wrongAnswerDelayMs;
      transitionTimer.current = window.setTimeout(() => {
        transitionTimer.current = null;
        if (nextIndex < cards.length) setIndex(nextIndex);
        else void finish();
      }, delay);
    } catch (caught) {
      setSyncError(caught instanceof Error ? caught.message : 'Could not save the answer.');
      setPhase('error');
    }
  }

  async function record(correct: boolean, seconds: number, attempts = 1, optionIndex: number | null = null, selectedAnswer = '') {
    if (phase !== 'idle' || answered !== undefined || !card) return;
    const correctAnswer = mode === 'typing-russian-to-english'
      || mode === 'russian-to-english'
      || mode === 'example-guess'
      || mode === 'image-to-english'
      || mode === 'audio-to-image'
      ? card.word
      : card.translation;
    const normalizedSelected = selectedAnswer || (optionIndex === null ? 'I don’t know' : card.options[optionIndex]?.label || '');
    const result: StudySessionAnswer = {
      wordId: card.wordId,
      word: card.word,
      translation: card.translation,
      prompt: card.prompt,
      selectedAnswer: normalizedSelected,
      correctAnswer,
      correct,
      seconds,
      attempts,
    };
    pendingAnswer.current = {
      answerId: createAnswerId(),
      correct,
      seconds,
      attempts,
      optionIndex,
      result,
    };
    await submitPending();
  }

  async function choose(optionIndex: number | null) {
    if (phase !== 'idle' || answered !== undefined || !card) return;
    const seconds = (performance.now() - started.current) / 1000;
    const correct = optionIndex !== null && card.options[optionIndex]?.wordId === card.wordId;
    await record(correct, seconds, 1, optionIndex, optionIndex === null ? 'I don’t know' : card.options[optionIndex]?.label || '');
  }

  async function submitTyping(event: FormEvent) {
    event.preventDefault();
    if (phase !== 'idle' || answered !== undefined || !typed.trim() || !card) return;
    const normalized = typed.trim().toLowerCase();
    const correct = normalized === card.word.trim().toLowerCase();
    if (correct) {
      setTypingMessage('Correct');
      await record(true, (performance.now() - started.current) / 1000, 4 - lives, 0, typed.trim());
      return;
    }
    const nextLives = lives - 1;
    setLives(nextLives);
    setTyped('');
    if (nextLives > 0) {
      setTypingMessage(`Wrong. ${nextLives} ${nextLives === 1 ? 'life' : 'lives'} left.`);
    } else {
      setTypingMessage(`Correct answer: ${card.word}`);
      await record(false, (performance.now() - started.current) / 1000, 3, null, normalized);
    }
  }

  if (!card) return null;

  const imageOnly = mode === 'image-to-english';
  const imageEnglish = mode === 'image-english-to-russian';
  const audioMode = mode === 'audio-to-russian' || mode === 'audio-to-image';
  const typingMode = mode === 'typing-russian-to-english';
  const audioImage = mode === 'audio-to-image';
  const images = (card.images?.length ? card.images : card.image ? [card.image] : []).slice(0, 4);
  const examplesCount = card.examples?.reduce((sum, group) => sum + (group.translations?.length || 0) + (group.phrases?.length || 0) + group.examples.length, 0) || 0;
  const promptLength = card.prompt?.length || 0;
  const promptClass = promptLength > 90 ? styles.promptLong : promptLength > 48 ? styles.promptMedium : '';
  const controlsDisabled = phase !== 'idle' || answered !== undefined;
  const rootClassName = [
    styles.root,
    examplesOpen ? styles.examplesVisible : '',
    typingMode ? styles.typingMode : '',
    keyboardOpen ? styles.keyboardOpen : '',
    imageEnglish ? styles.imageEnglishMode : '',
  ].filter(Boolean).join(' ');

  return <div className={rootClassName}>
    <header>
      <div><strong>{index + 1}/{cards.length}</strong><span>{elapsed.toFixed(1)} s</span></div>
      <div className={styles.headerActions}><Button onClick={() => void pause()} disabled={phase === 'submitting' || phase === 'finishing'}><Pause size={16}/>Pause</Button><Button onClick={() => void finish()} disabled={phase === 'submitting' || phase === 'finishing'}>{phase === 'finishing' ? 'Saving…' : 'End'}</Button></div>
    </header>
    <div className={styles.progress}><i style={{ width: `${index / cards.length * 100}%` }}/></div>

    <section className={styles.card}>
      <div className={styles.frequency}><FrequencyBadge rank={card.frequencyRank}/></div>
      <span className={styles.timer}>{elapsed.toFixed(1)} s</span>
      {audioMode && <button type="button" className={styles.audioPrompt} onClick={() => void playAudio().catch(() => undefined)}><Volume2/><strong>Play again</strong></button>}
      {(imageOnly || imageEnglish) ? (images.length ? <div className={styles.mainImages}><WordImageGrid images={images} alt="Study prompt" square/></div> : <div className={styles.noImage}><ImageOff/>Image unavailable</div>) : null}
      {!imageOnly && !audioMode && <>
        <h1 className={`${mode === 'example-guess' ? styles.examplePrompt : ''} ${promptClass}`}>{card.prompt}</h1>
        {!typingMode && mode !== 'russian-to-english' && mode !== 'example-guess' && <PronunciationList word={card.word} transcription={card.transcription} audio={card.audio}/>} 
        {card.example && <p><HighlightedText text={card.example} word={card.word}/></p>}
      </>}
      {typingMode && <div className={styles.lives} aria-label={`${lives} lives`}>{[0, 1, 2].map((item) => <Heart key={item} className={item < lives ? styles.live : styles.lost} fill="currentColor"/>)}</div>}
    </section>

    <div className={styles.examplesBlock}>
      <button type="button" onClick={() => setExamplesOpen((value) => !value)} disabled={(imageOnly || audioImage) && answered === undefined}><span>Dictionary details {examplesCount ? `(${examplesCount})` : ''}</span><ChevronDown className={examplesOpen ? styles.rotated : undefined} size={17}/></button>
      {examplesOpen && <div className={styles.examplesPanel}><UsageExamples groups={card.examples} word={card.word}/></div>}
    </div>

    {syncError && <div className={styles.syncError} role="alert">
      <AlertTriangle size={19}/><span><strong>{pendingAnswer.current ? 'Answer was not confirmed' : 'Session could not be saved'}</strong><small>{syncError}</small></span>
      {pendingAnswer.current ? <Button onClick={() => void submitPending()}><RefreshCw size={15}/>Retry</Button> : <Button onClick={() => void finish()}><RefreshCw size={15}/>Retry</Button>}
    </div>}


    {typingMode ? <form className={styles.typing} onSubmit={(event) => void submitTyping(event)}>
      <input ref={typingInput} autoFocus autoCapitalize="none" autoCorrect="off" spellCheck={false} value={typed} disabled={controlsDisabled} onChange={(event) => setTyped(event.target.value)} placeholder="Type the English word"/>
      <Button variant="primary" disabled={controlsDisabled || !typed.trim()} type="submit">{phase === 'submitting' ? 'Saving…' : 'Check'}</Button>
      {typingMessage && <p>{typingMessage}</p>}
    </form> : <>
      <div className={`${styles.options} ${audioImage ? styles.imageOptions : ''}`}>{card.options.map((option, optionIndex) => {
        const isCorrect = option.wordId === card.wordId;
        const state = answered === undefined ? '' : isCorrect ? styles.correct : answered === optionIndex ? styles.wrong : styles.dim;
        return <button key={`${option.wordId}-${optionIndex}`} className={state} disabled={controlsDisabled} onClick={() => void choose(optionIndex)}>{audioImage && option.image ? <img src={api.imageUrl(option.image)} alt="Answer option"/> : <><b>{optionIndex + 1}</b>{option.label}</>}</button>;
      })}</div>
      <Button className={styles.dontKnow} variant="danger" fullWidth disabled={controlsDisabled} onClick={() => void choose(null)}>I don’t know</Button>
    </>}
  </div>;
}
