import type { ButtonHTMLAttributes, PropsWithChildren } from 'react';
import { classNames } from 'shared/lib/classNames';
import styles from './Button.module.sass';
type Variant = 'primary' | 'secondary' | 'ghost' | 'danger';
interface Props extends ButtonHTMLAttributes<HTMLButtonElement> { variant?: Variant; fullWidth?: boolean; }
export function Button({ variant = 'secondary', fullWidth, className, children, ...props }: PropsWithChildren<Props>) {
  return <button className={classNames(styles.button, styles[variant], fullWidth && styles.fullWidth, className)} {...props}>{children}</button>;
}
