import type { ReactNode } from 'react';
import styles from './PageHeader.module.sass';
export function PageHeader({title,subtitle,actions}:{title:string;subtitle:string;actions?:ReactNode}){return<header className={styles.root}><div><h1>{title}</h1><p>{subtitle}</p></div>{actions&&<div className={styles.actions}>{actions}</div>}</header>}
