import { useState, type FormEvent } from 'react';
import { useAuth } from 'app/providers/AuthProvider';
import { Button } from 'shared/ui/Button';
import { Field, Input } from 'shared/ui/Form';
import styles from './AuthForm.module.sass';
export function AuthForm() {
  const { login, register } = useAuth();
  const [mode,setMode]=useState<'login'|'register'>('login'); const [username,setUsername]=useState(''); const [displayName,setDisplayName]=useState(''); const [password,setPassword]=useState(''); const [error,setError]=useState(''); const [busy,setBusy]=useState(false);
  async function submit(event:FormEvent){event.preventDefault();setBusy(true);setError('');try{if(mode==='login')await login(username,password);else await register(username,displayName,password);}catch(e){setError(e instanceof Error?e.message:'Authentication failed');}finally{setBusy(false)}}
  return <section className={styles.card}>
    <div className={styles.brand}><span>V</span><strong>VocabFlow</strong></div>
    <div className={styles.copy}><h1>{mode==='login'?'Welcome back':'Create your account'}</h1><p>Your vocabulary and learning progress stay private to your account.</p></div>
    <div className={styles.tabs}><button className={mode==='login'?styles.active:''} onClick={()=>setMode('login')}>Log in</button><button className={mode==='register'?styles.active:''} onClick={()=>setMode('register')}>Register</button></div>
    <form onSubmit={submit}>
      {mode==='register'&&<Field label="Display name"><Input value={displayName} onChange={e=>setDisplayName(e.target.value)} autoComplete="name" placeholder="Your name"/></Field>}
      <Field label="Username"><Input value={username} onChange={e=>setUsername(e.target.value)} autoCapitalize="none" autoComplete="username" placeholder="username"/></Field>
      <Field label="Password" hint={mode==='register'?'At least 8 characters.':''}><Input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete={mode==='login'?'current-password':'new-password'} placeholder="••••••••"/></Field>
      {error&&<div className={styles.error}>{error}</div>}
      <Button variant="primary" fullWidth disabled={busy}>{busy?'Please wait…':mode==='login'?'Log in':'Create account'}</Button>
    </form>
    <p className={styles.security}>Passwords are hashed with scrypt and a unique salt. Plain-text passwords are never stored.</p>
  </section>;
}
