import { Headphones, Image, Keyboard, Languages, Quote } from 'lucide-react';
import type { StudyMode } from 'entities/study/model/types';
import { STUDY_MODE_META } from 'entities/study/model/types';
import styles from './StudyModeSelector.module.sass';
const modes: StudyMode[]=['image-english-to-russian','image-to-english','english-to-russian','russian-to-english','audio-to-russian','audio-to-image','example-guess','typing-russian-to-english'];
function icon(mode:StudyMode){if(mode==='audio-to-russian'||mode==='audio-to-image')return <Headphones/>;if(mode==='typing-russian-to-english')return <Keyboard/>;if(mode==='example-guess')return <Quote/>;if(mode.startsWith('image-'))return <Image/>;return <Languages/>}
export function StudyModeSelector({value,onChange,imageCount,audioCount,exampleCount}:{value:StudyMode;onChange:(mode:StudyMode)=>void;imageCount:number;audioCount:number;exampleCount:number}){return <div className={styles.grid}>{modes.map(mode=>{const needsImage=mode.startsWith('image-')||mode==='audio-to-image';const needsAudio=mode.startsWith('audio-');const needsExample=mode==='example-guess';const disabled=(needsImage&&imageCount===0)||(needsAudio&&audioCount===0)||(needsExample&&exampleCount===0);const meta=STUDY_MODE_META[mode];return <button type="button" key={mode} className={`${styles.card} ${value===mode?styles.active:''}`} disabled={disabled} onClick={()=>onChange(mode)}>{icon(mode)}<strong>{meta.title}</strong><span>{meta.description}</span>{disabled&&<small>Not enough suitable words for this mode.</small>}</button>})}</div>}
