import { useEffect, useMemo, useRef, useState } from 'react';
import { ChevronDown, Languages, LoaderCircle, RefreshCw, Volume2 } from 'lucide-react';
import type { WordAudio, WordExampleGroup, WordPronunciation } from 'entities/word/model/types';
import { api } from 'shared/api/apiClient';
import { cleanTranscription } from 'shared/lib/transcription';
import { UsageExamples } from 'shared/ui/UsageExamples';
import { Button } from 'shared/ui/Button';
import { FrequencyBadge } from 'shared/ui/FrequencyBadge';
import { Field, Input, Textarea } from 'shared/ui/Form';
import styles from './WordEnrichment.module.sass';

interface Props {
  english: string;
  russian: string;
  onRussianChange: (value: string) => void;
  transcription: WordPronunciation;
  onTranscriptionChange: (value: WordPronunciation) => void;
  audio: WordAudio;
  onAudioChange: (value: WordAudio) => void;
  partsOfSpeech: string[];
  onPartsOfSpeechChange: (value: string[]) => void;
  examples: WordExampleGroup[];
  onExamplesChange: (value: WordExampleGroup[]) => void;
  frequencyRank?: number | null;
  onFrequencyRankChange: (value: number | null) => void;
  autoLookup?: boolean;
}

export function WordEnrichment(props: Props) {
  const { english, russian, onRussianChange, transcription, onTranscriptionChange, audio, onAudioChange, partsOfSpeech, onPartsOfSpeechChange, examples, onExamplesChange, frequencyRank, onFrequencyRankChange, autoLookup = true } = props;
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState('Word details will load automatically from WooordHunt.');
  const [examplesOpen, setExamplesOpen] = useState(false);
  const [playing, setPlaying] = useState<'american' | 'british' | null>(null);
  const lastAutoTranslationRef = useRef('');
  const requestVersionRef = useRef(0);
  const lastLookupWordRef = useRef('');
  const examplesCount = useMemo(() => examples.reduce((sum, group) => sum + (group.translations?.length || 0) + (group.phrases?.length || 0) + group.examples.length, 0), [examples]);

  async function lookup(forceReplace = false): Promise<void> {
    const word = english.trim();
    if (word.length < 2) return;
    const version = ++requestVersionRef.current;
    setLoading(true);
    setStatus('Loading translation, transcription, pronunciation and examples…');
    try {
      const result = await api.lookupTranslation(word);
      if (requestVersionRef.current !== version) return;
      const canReplaceTranslation = forceReplace || !russian.trim() || russian === lastAutoTranslationRef.current;
      if (canReplaceTranslation) { onRussianChange(result.translation); lastAutoTranslationRef.current = result.translation; }
      onTranscriptionChange({
        american: cleanTranscription(result.transcription?.american || ''),
        british: cleanTranscription(result.transcription?.british || ''),
      });
      onAudioChange(result.audio || { american: '', british: '' });
      onPartsOfSpeechChange(result.partsOfSpeech || []);
      onExamplesChange(result.examples || []);
      onFrequencyRankChange(result.frequencyRank || null);
      lastLookupWordRef.current = word.toLowerCase();
      setStatus(canReplaceTranslation ? 'Loaded from WooordHunt. Every field can still be edited.' : `WooordHunt suggestion: ${result.translation}`);
    } catch (error) {
      if (requestVersionRef.current !== version) return;
      setStatus(error instanceof Error ? error.message : 'Could not load word details.');
    } finally { if (requestVersionRef.current === version) setLoading(false); }
  }

  useEffect(() => {
    if (!autoLookup) return undefined;
    const word = english.trim();
    if (word.length < 2 || lastLookupWordRef.current === word.toLowerCase()) return undefined;
    const timer = window.setTimeout(() => void lookup(false), 500);
    return () => { window.clearTimeout(timer); requestVersionRef.current += 1; };
  }, [english, autoLookup]);

  async function play(accent: 'american' | 'british'): Promise<void> {
    const url = audio[accent]; if (!url) return;
    setPlaying(accent);
    try { await api.playPronunciation(url, english, accent === 'american' ? 'en-US' : 'en-GB'); }
    catch (error) { setStatus(error instanceof Error ? error.message : 'Could not play pronunciation.'); }
    finally { setPlaying(null); }
  }

  return <div className={styles.root}>
    <Field label="Russian" hint={status}>
      <div className={styles.translationRow}>
        <div className={styles.inputWrap}><Languages size={18}/><Textarea value={russian} onChange={event=>onRussianChange(event.target.value)} placeholder="Translation will appear here" rows={4}/></div>
        <Button type="button" variant="secondary" disabled={loading || english.trim().length < 2} onClick={()=>void lookup(true)}>{loading?<LoaderCircle className={styles.spinner} size={17}/>:<RefreshCw size={17}/>}<span>WooordHunt</span></Button>
      </div>
    </Field>

    <div className={styles.metaGrid}>
      <Field label="US transcription">
        <div className={styles.audioField}><Input value={transcription.american} onChange={event=>onTranscriptionChange({...transcription,american:cleanTranscription(event.target.value)})} placeholder="sleɪ"/><button type="button" disabled={!audio.american || playing!==null} onClick={()=>void play('american')} title="Play American pronunciation"><Volume2 size={16}/></button></div>
      </Field>
      <Field label="UK transcription">
        <div className={styles.audioField}><Input value={transcription.british} onChange={event=>onTranscriptionChange({...transcription,british:cleanTranscription(event.target.value)})} placeholder="sleɪ"/><button type="button" disabled={!audio.british || playing!==null} onClick={()=>void play('british')} title="Play British pronunciation"><Volume2 size={16}/></button></div>
      </Field>
    </div>

    <div className={styles.frequencyRow}><span>Word frequency</span><FrequencyBadge rank={frequencyRank}/></div>

    <Field label="Parts of speech" hint="Multiple values are separated with commas."><Input value={partsOfSpeech.join(', ')} onChange={event=>onPartsOfSpeechChange(event.target.value.split(',').map(value=>value.trim().toLowerCase()).filter(Boolean))} placeholder="noun, verb"/></Field>

    <div className={styles.examplesBlock}>
      <button type="button" className={styles.examplesToggle} onClick={()=>setExamplesOpen(value=>!value)} aria-expanded={examplesOpen}><span>Usage examples {examplesCount?`(${examplesCount})`:''}</span><ChevronDown className={examplesOpen?styles.rotated:undefined} size={17}/></button>
      {examplesOpen&&<div className={styles.examplesPanel}>{examples.length?<UsageExamples groups={examples} word={english}/>:<p className={styles.noExamples}>No dictionary details were found.</p>}</div>}
    </div>
  </div>;
}
