import { useEffect, useState } from 'react';
import { KeyRound, LogOut, Save, ShieldCheck, UserRound, Volume2 } from 'lucide-react';
import { useAuth } from 'app/providers/AuthProvider';
import { useData } from 'app/providers/DataProvider';
import type { Settings } from 'entities/settings/model/types';
import type { StudyMode } from 'entities/study/model/types';
import { STUDY_MODE_META } from 'entities/study/model/types';
import { Button } from 'shared/ui/Button';
import { Field, Input, Select } from 'shared/ui/Form';
import { PageHeader } from 'widgets/PageHeader';
import styles from './AccountPage.module.sass';

export function AccountPage() {
  const { user, logout, changePassword } = useAuth();
  const { settings, saveSettings } = useData();
  const [local, setLocal] = useState<Settings | null>(settings);
  const [saved, setSaved] = useState(false);
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordMessage, setPasswordMessage] = useState<{ tone: 'error' | 'success'; text: string } | null>(null);
  const [changing, setChanging] = useState(false);

  useEffect(() => setLocal(settings), [settings]);

  async function save() {
    if (!local) return;
    await saveSettings(local);
    setSaved(true);
    window.setTimeout(() => setSaved(false), 1600);
  }

  async function submitPassword(event: React.FormEvent) {
    event.preventDefault();
    setPasswordMessage(null);
    if (newPassword.length < 8) return setPasswordMessage({ tone: 'error', text: 'New password must be at least 8 characters.' });
    if (newPassword !== confirmPassword) return setPasswordMessage({ tone: 'error', text: 'New password and confirmation do not match.' });
    if (newPassword === currentPassword) return setPasswordMessage({ tone: 'error', text: 'New password must be different from the current password.' });
    setChanging(true);
    try {
      await changePassword(currentPassword, newPassword);
      setCurrentPassword(''); setNewPassword(''); setConfirmPassword('');
      setPasswordMessage({ tone: 'success', text: 'Password changed successfully.' });
    } catch (error) {
      setPasswordMessage({ tone: 'error', text: error instanceof Error ? error.message : 'Could not change password.' });
    } finally { setChanging(false); }
  }

  return <>
    <PageHeader title="Account" subtitle="Manage your profile, study preferences, password, and session." />

    <section className={styles.profile}>
      <div className={styles.avatar}>{user?.displayName.slice(0, 2).toUpperCase()}</div>
      <div><span>Signed in as</span><h2>{user?.displayName}</h2><p>@{user?.username}</p></div>
      <div className={styles.created}><UserRound size={18}/><span>Member since</span><strong>{user ? new Date(user.createdAt).toLocaleDateString() : '—'}</strong></div>
    </section>

    {local && <section className={styles.panel}>
      <div className={styles.sectionTitle}><div><h2>Study settings</h2><p>Tune automatic scoring and study display.</p></div><Save size={20}/></div>
      <div className={styles.grid}>
        <Field label="Fast answer threshold (seconds)"><Input type="number" min="0.5" step="0.5" value={local.fastSeconds} onChange={(event) => setLocal({ ...local, fastSeconds: Number(event.target.value) })}/></Field>
        <Field label="Slow answer threshold (seconds)"><Input type="number" min="1" step="0.5" value={local.slowSeconds} onChange={(event) => setLocal({ ...local, slowSeconds: Number(event.target.value) })}/></Field>
        <Field label="Correct answer delay (milliseconds)"><Input type="number" min="50" max="5000" step="50" value={local.correctAnswerDelayMs} onChange={(event) => setLocal({ ...local, correctAnswerDelayMs: Number(event.target.value) })}/></Field>
        <Field label="Wrong answer delay (milliseconds)"><Input type="number" min="50" max="5000" step="50" value={local.wrongAnswerDelayMs} onChange={(event) => setLocal({ ...local, wrongAnswerDelayMs: Number(event.target.value) })}/></Field>
        <Field label="Default study mode"><Select value={local.defaultStudyMode} onChange={(event) => setLocal({ ...local, defaultStudyMode: event.target.value as StudyMode })}>{Object.entries(STUDY_MODE_META).map(([id, meta]) => <option value={id} key={id}>{meta.title}</option>)}</Select></Field>
        <Field label="Example highlight color"><div className={styles.colorField}><input type="color" value={local.exampleHighlightColor || '#ff6b7a'} onChange={(event) => setLocal({ ...local, exampleHighlightColor: event.target.value })}/><Input value={local.exampleHighlightColor || '#ff6b7a'} onChange={(event) => setLocal({ ...local, exampleHighlightColor: event.target.value })}/></div></Field>
      </div>
      <div className={styles.checks}>
        <label className={styles.optionRow}><input type="checkbox" checked={local.autoSpeak} onChange={(event) => setLocal({ ...local, autoSpeak: event.target.checked })}/><span className={styles.optionCopy}><strong><Volume2 size={16}/>Auto-speak prompts</strong><small>Automatically plays the prompt voice when a new study card appears.</small></span></label>
      </div>
      <Button variant="primary" onClick={() => void save()}>{saved ? 'Saved' : 'Save settings'}</Button>
    </section>}

    <section className={styles.panel}>
      <div className={styles.sectionTitle}><div><h2>Change password</h2><p>Your current password is required to set a new one.</p></div><KeyRound size={20}/></div>
      <form className={styles.passwordForm} onSubmit={(event) => void submitPassword(event)}>
        <Field label="Current password"><Input type="password" autoComplete="current-password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)}/></Field>
        <Field label="New password"><Input type="password" autoComplete="new-password" value={newPassword} onChange={(event) => setNewPassword(event.target.value)}/></Field>
        <Field label="Confirm new password"><Input type="password" autoComplete="new-password" value={confirmPassword} onChange={(event) => setConfirmPassword(event.target.value)}/></Field>
        {passwordMessage && <div className={passwordMessage.tone === 'success' ? styles.success : styles.error}>{passwordMessage.text}</div>}
        <Button variant="primary" type="submit" disabled={changing || !currentPassword || !newPassword || !confirmPassword}>{changing ? 'Changing…' : 'Change password'}</Button>
      </form>
    </section>

    <section className={`${styles.panel} ${styles.logoutPanel}`}>
      <div><ShieldCheck size={22}/><span><h2>Session</h2><p>Log out on this device.</p></span></div>
      <Button onClick={() => void logout()}><LogOut size={17}/>Log out</Button>
    </section>
  </>;
}
