import { useState } from 'react';
import { useData } from 'app/providers/DataProvider';
import type { Word } from 'entities/word/model/types';
import { Button } from 'shared/ui/Button';
import { Field, Select, Textarea } from 'shared/ui/Form';
import { Modal } from 'shared/ui/Modal';
import styles from './ImportWords.module.sass';

function parse(text: string): Array<Partial<Word>> {
  return text
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const parts = line.includes('\t')
        ? line.split('\t')
        : line.includes(';')
          ? line.split(';')
          : line.includes(' — ')
            ? line.split(' — ')
            : line.split(',');

      return {
        word: parts[0]?.trim(),
        translation: parts[1]?.trim(),
        example: parts.slice(2).join(' ').trim(),
        partOfSpeech: 'noun' as const,
      };
    })
    .filter((item) => Boolean(item.word && item.translation));
}

export function ImportWords({ onClose }: { onClose: () => void }) {
  const { folders, importWords } = useData();
  const [folderId, setFolderId] = useState(folders[0]?.id || '');
  const [text, setText] = useState('countertop — столешница\ndrawer — выдвижной ящик');
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');

  async function run() {
    setBusy(true);
    try {
      const count = await importWords(folderId, parse(text));
      setMessage(`${count} words imported.`);
      window.setTimeout(onClose, 700);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : 'Import failed');
    } finally {
      setBusy(false);
    }
  }

  return (
    <Modal title="Import words" onClose={onClose}>
      <div className={styles.form}>
        <Field label="Destination folder">
          <Select value={folderId} onChange={(event) => setFolderId(event.target.value)}>
            {folders.map((folder) => (
              <option key={folder.id} value={folder.id}>{folder.name}</option>
            ))}
          </Select>
        </Field>
        <Field
          label="Word list"
          hint="One pair per line. Supported separators: tab, semicolon, comma, or em dash."
        >
          <Textarea value={text} onChange={(event) => setText(event.target.value)} />
        </Field>
        {message && <p>{message}</p>}
        <div className={styles.actions}>
          <Button onClick={onClose}>Cancel</Button>
          <Button variant="primary" onClick={() => void run()} disabled={busy || !folderId}>
            {busy ? 'Importing…' : 'Import'}
          </Button>
        </div>
      </div>
    </Modal>
  );
}
