import { PauseCircle, Play, RotateCcw } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { useData } from 'app/providers/DataProvider';
import type { ActiveStudySession, ActiveStudySessionSave, StudyCard, StudyMode } from 'entities/study/model/types';
import { StudyModeSelector } from 'features/study-mode-selector';
import { StudySessionView } from 'features/study-session';
import { api } from 'shared/api/apiClient';
import { Button } from 'shared/ui/Button';
import { Field, Select } from 'shared/ui/Form';
import { PageHeader } from 'widgets/PageHeader';
import styles from './StudyPage.module.sass';

function createSessionId() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
  return `study-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
}

export function StudyPage() {
  const { folders, words, settings, reload } = useData();
  const [params] = useSearchParams();
  const initialFolder = params.get('folder') || 'all';
  const specificWord = params.get('word');
  const autostart = params.get('autostart') === '1';

  const [folderId, setFolderId] = useState(initialFolder);
  const [mode, setMode] = useState<StudyMode>(settings?.defaultStudyMode || 'english-to-russian');
  const [cards, setCards] = useState<StudyCard[]>([]);
  const [resume, setResume] = useState<ActiveStudySession | null>(null);
  const [sessionInitial, setSessionInitial] = useState<ActiveStudySession | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const autoStarted = useRef(false);

  useEffect(() => { if (settings) setMode(settings.defaultStudyMode); }, [settings]);
  useEffect(() => {
    void api.getActiveStudySession()
      .then(setResume)
      .catch((caught) => setError(caught instanceof Error ? caught.message : 'Could not load the unfinished session.'));
  }, []);

  const imageCount = words.filter((word) => (word.images?.length || word.image)).length;
  const audioCount = words.filter((word) => word.audio?.american || word.audio?.british).length;
  const exampleCount = words.filter((word) => (word.examples || []).some((group) => (group.examples || []).some((example) => example.english.toLowerCase().includes(word.word.toLowerCase())))).length;

  async function start() {
    if (!settings || loading) return;
    setLoading(true);
    setError('');
    try {
      const queue = await api.studyQueue({
        folderId: folderId === 'all' ? undefined : folderId,
        wordId: specificWord || undefined,
        mode,
      });
      if (!queue.length) {
        throw new Error(
          (mode.startsWith('image-') || mode === 'audio-to-image')
            ? 'No suitable words with images are available for this mode.'
            : mode.startsWith('audio-')
              ? 'No words with audio are available for this mode.'
              : mode === 'example-guess'
                ? 'No words with usable examples are available for this mode.'
                : 'No words are available for this selection.',
        );
      }

      const active: ActiveStudySessionSave = {
        sessionId: createSessionId(),
        wordIds: queue.map((card) => card.wordId),
        index: 0,
        correctCount: 0,
        times: [],
        answers: [],
        folderId: folderId === 'all' ? null : folderId,
        mode,
        elapsed: 0,
        processedAnswerIds: [],
      };
      const saved = await api.saveActiveStudySession(active);
      setSessionInitial(saved);
      setCards(queue);
      setResume(null);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Could not start the session.');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    if (!autostart || autoStarted.current || !settings || loading || cards.length) return;
    autoStarted.current = true;
    void start();
  }, [autostart, settings, loading, cards.length, folderId, mode, specificWord]);

  async function resumeSession() {
    if (!resume || loading) return;
    if (resume.index >= resume.cards.length) {
      setLoading(true);
      setError('');
      try {
        await api.saveSession(resume.sessionId);
        setResume(null);
        void reload().catch(() => undefined);
      } catch (caught) {
        setError(caught instanceof Error ? caught.message : 'Could not finish the saved session.');
      } finally {
        setLoading(false);
      }
      return;
    }
    setFolderId(resume.folderId || 'all');
    setMode(resume.mode);
    setSessionInitial(resume);
    setCards(resume.cards);
    setResume(null);
  }

  async function discard() {
    if (loading) return;
    setLoading(true);
    setError('');
    try {
      await api.clearActiveStudySession();
      setResume(null);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Could not discard the session.');
    } finally {
      setLoading(false);
    }
  }

  if (cards.length && settings && sessionInitial) {
    return <StudySessionView
      cards={cards}
      settings={settings}
      folderId={folderId === 'all' ? null : folderId}
      mode={mode}
      initial={sessionInitial}
      onFinish={() => { setCards([]); setSessionInitial(null); setResume(null); }}
      onPause={(state) => { setResume(state); setCards([]); setSessionInitial(null); }}
      onWordUpdated={reload}
    />;
  }

  const resumeComplete = Boolean(resume && resume.index >= resume.cards.length);
  return <>
    <PageHeader title="Study" subtitle="Choose a mode and study every eligible word in the selected collection. Unfinished sessions can be resumed anytime."/>
    {resume && <section className={styles.resume}>
      <div><PauseCircle/><span><strong>{resumeComplete ? 'Session ready to finish' : 'Paused session'}</strong><small>{Math.min(resume.index, resume.cards.length)} of {resume.cards.length} cards completed · {resume.mode.replaceAll('-', ' ')}</small></span></div>
      <div><Button onClick={() => void discard()} disabled={loading}><RotateCcw size={16}/>Discard</Button><Button variant="primary" onClick={() => void resumeSession()} disabled={loading}><Play size={16}/>{resumeComplete ? 'Save results' : 'Resume'}</Button></div>
    </section>}
    <section className={styles.panel}>
      <div className={styles.compactHead}><h2>Learning mode</h2><div className={styles.inlineControls}><Field label="Folder"><Select value={folderId} onChange={(event) => setFolderId(event.target.value)}><option value="all">All folders</option>{folders.map((folder) => <option key={folder.id} value={folder.id}>{folder.name}</option>)}</Select></Field><Button variant="primary" onClick={() => void start()} disabled={loading || !words.length}><Play size={17}/>{loading ? 'Preparing…' : 'Start'}</Button></div></div>
      <StudyModeSelector value={mode} onChange={setMode} imageCount={imageCount} audioCount={audioCount} exampleCount={exampleCount}/>
      {error && <p className={styles.error}>{error}</p>}
    </section>
  </>;
}
