import { Image as ImageIcon, Plus, Upload } from 'lucide-react';
import { useMemo, useState } from 'react';
import { useData } from 'app/providers/DataProvider';
import type { Word } from 'entities/word/model/types';
import { ImportWords } from 'features/import-words';
import { WordDetailsModal } from 'features/word-details';
import { WordEditor } from 'features/word-editor';
import { Button } from 'shared/ui/Button';
import { Select } from 'shared/ui/Form';
import { WordTable } from 'shared/ui/WordTable';
import { PageHeader } from 'widgets/PageHeader';
import styles from './WordsPage.module.sass';

export function WordsPage(){
  const { words, folders } = useData();
  const [folder, setFolder] = useState('all');
  const [editing, setEditing] = useState<Word | undefined>();
  const [viewing, setViewing] = useState<Word | undefined>();
  const [editorOpen, setEditorOpen] = useState(false);
  const [importOpen, setImportOpen] = useState(false);

  const filtered = useMemo(() => words.filter((word) => folder === 'all' || word.folderId === folder), [words, folder]);

  return <>
    <PageHeader title="Words" subtitle="Manage your personal dictionary and open any word by clicking its row." actions={<><Button onClick={() => setImportOpen(true)}><Upload size={17}/>Import</Button><Button variant="primary" onClick={() => { setEditing(undefined); setEditorOpen(true); }}><Plus size={17}/>Add word</Button></>}/>
    <section className={styles.panel}>
      <div className={styles.toolbar}><Select value={folder} onChange={(event) => setFolder(event.target.value)}><option value="all">All folders</option>{folders.map((folderItem) => <option value={folderItem.id} key={folderItem.id}>{folderItem.name}</option>)}</Select><span className={styles.count}>{filtered.length} word{filtered.length === 1 ? '' : 's'}</span></div>
      <WordTable words={filtered} folders={folders} onOpen={setViewing}/>
      {filtered.length === 0 && <div className={styles.empty}><ImageIcon/>No words in this selection</div>}
    </section>
    {viewing && <WordDetailsModal word={viewing} onClose={() => setViewing(undefined)} onEdit={() => { setEditing(viewing); setViewing(undefined); setEditorOpen(true); }}/>} 
    {editorOpen && <WordEditor word={editing} onClose={() => setEditorOpen(false)}/>} {importOpen && <ImportWords onClose={() => setImportOpen(false)}/>} 
  </>;
}
