import type { WordAudio, WordExampleGroup, WordPronunciation } from 'entities/word/model/types';

export type StudyMode =
  | 'english-to-russian'
  | 'russian-to-english'
  | 'image-to-english'
  | 'image-english-to-russian'
  | 'audio-to-russian'
  | 'audio-to-image'
  | 'example-guess'
  | 'typing-russian-to-english';

export interface StudyOption { wordId: string; label: string; image?: string; }

export interface StudyCard {
  wordId: string;
  mode: StudyMode;
  prompt: string | null;
  image: string | null;
  images: string[];
  word: string;
  translation: string;
  transcription: WordPronunciation;
  audio: WordAudio;
  frequencyRank?: number | null;
  partsOfSpeech: string[];
  examples: WordExampleGroup[];
  example: string;
  options: StudyOption[];
}

export interface StudyResult { count: number; correct: number; averageTime: number; }

