export interface StudySessionAnswer {
  wordId: string;
  word: string;
  translation: string;
  prompt: string | null;
  selectedAnswer: string;
  correctAnswer: string;
  correct: boolean;
  seconds: number;
  attempts: number;
}

export interface ActiveStudySessionSummary {
  sessionId: string;
  index: number;
  total: number;
  correctCount: number;
  folderId: string | null;
  mode: StudyMode;
  elapsed: number;
  pausedAt: number;
  updatedAt: number;
}

export interface ActiveStudySession {
  sessionId: string;
  wordIds: string[];
  cards: StudyCard[];
  index: number;
  correctCount: number;
  times: number[];
  answers: StudySessionAnswer[];
  folderId: string | null;
  mode: StudyMode;
  elapsed: number;
  processedAnswerIds: string[];
  pausedAt: number;
  updatedAt: number;
}

export interface ActiveStudySessionSave {
  sessionId: string;
  wordIds: string[];
  index: number;
  correctCount: number;
  times: number[];
  answers: StudySessionAnswer[];
  folderId: string | null;
  mode: StudyMode;
  elapsed: number;
  processedAnswerIds?: string[];
}

export interface StudyAnswerRequest {
  sessionId: string;
  answerId: string;
  wordId: string;
  correct: boolean;
  seconds: number;
  attempts: number;
  result: StudySessionAnswer;
}
