import {
  BookOpen,
  Brain,
  CalendarDays,
  Check,
  ChevronRight,
  Clock3,
  Flame,
  FolderOpen,
  Layers3,
  Play,
  Sparkles,
  Target,
  TrendingUp,
  X,
} from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from 'app/providers/AuthProvider';
import { useData } from 'app/providers/DataProvider';
import type { StudySession } from 'entities/session/model/types';
import type { ActiveStudySessionSummary } from 'entities/study/model/types';
import { api } from 'shared/api/apiClient';
import { Button } from 'shared/ui/Button';
import styles from './DashboardPage.module.sass';

const DAY = 86_400_000;

function dayKey(timestamp: number) {
  const date = new Date(timestamp);
  return `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
}

function getStreak(sessions: StudySession[]) {
  const days = new Set(sessions.map((session) => dayKey(session.date)));
  const cursor = new Date();
  if (!days.has(dayKey(cursor.getTime()))) cursor.setDate(cursor.getDate() - 1);
  let streak = 0;
  while (days.has(dayKey(cursor.getTime()))) {
    streak += 1;
    cursor.setDate(cursor.getDate() - 1);
  }
  return streak;
}

export function DashboardPage() {
  const { user } = useAuth();
  const { folders, words, sessions } = useData();
  const navigate = useNavigate();
  const [selectedSession, setSelectedSession] = useState<StudySession | null>(null);
  const [activeSession, setActiveSession] = useState<ActiveStudySessionSummary | null>(null);

  useEffect(() => {
    void api.getActiveStudySessionSummary().then(setActiveSession).catch(() => undefined);
  }, []);

  useEffect(() => {
    if (!selectedSession) return;
    window.dispatchEvent(new CustomEvent('vocabflow-overlay-activity', { detail: 1 }));
    return () => { window.dispatchEvent(new CustomEvent('vocabflow-overlay-activity', { detail: -1 })); };
  }, [selectedSession]);

  const learned = words.filter((word) => word.score >= 75).length;
  const learning = words.filter((word) => word.score >= 45 && word.score < 75).length;
  const weak = words.filter((word) => word.score < 45).length;
  const dueWords = words.filter((word) => word.dueAt <= Date.now());
  const reviews = words.reduce((sum, word) => sum + word.reviews, 0);
  const correct = words.reduce((sum, word) => sum + word.correct, 0);
  const accuracy = reviews ? Math.round(correct / reviews * 100) : 0;
  const average = reviews ? words.reduce((sum, word) => sum + word.totalTime, 0) / reviews : 0;
  const knownPercent = words.length ? Math.round(learned / words.length * 100) : 0;
  const streak = getStreak(sessions);
  const firstName = user?.displayName.split(/\s+/)[0] || 'there';
  const hour = new Date().getHours();
  const greeting = hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening';

  const folderStats = useMemo(() => folders.map((folder) => {
    const list = words.filter((word) => word.folderId === folder.id);
    const known = list.filter((word) => word.score >= 75).length;
    const due = list.filter((word) => word.dueAt <= Date.now()).length;
    return { folder, count: list.length, known, due, percent: list.length ? Math.round(known / list.length * 100) : 0 };
  }).sort((a, b) => b.due - a.due || b.count - a.count), [folders, words]);

  const activity = useMemo(() => Array.from({ length: 7 }, (_, index) => {
    const date = new Date(Date.now() - (6 - index) * DAY);
    const key = dayKey(date.getTime());
    const list = sessions.filter((session) => dayKey(session.date) === key);
    return {
      label: date.toLocaleDateString(undefined, { weekday: 'short' }).slice(0, 2),
      count: list.reduce((sum, session) => sum + session.count, 0),
      sessions: list.length,
      today: index === 6,
    };
  }), [sessions]);
  const maxActivity = Math.max(1, ...activity.map((item) => item.count));
  const recentSessions = sessions.slice().sort((a, b) => b.date - a.date).slice(0, 6);
  const nextWord = dueWords[0] || words.slice().sort((a, b) => a.score - b.score)[0];
  const ringBackground = `conic-gradient(var(--accent-2) ${knownPercent * 3.6}deg, var(--panel-3) 0deg)`;

  return <>
    <header className={styles.welcome}>
      <div><span>{greeting}, {firstName}</span><h1>Keep your English moving.</h1><p>Review what is fading, strengthen weak words, and keep your learning rhythm.</p></div>
      <Button variant="primary" onClick={() => navigate('/study')}><Play size={17}/>Open study hub</Button>
    </header>

    <section className={styles.heroGrid}>
      <article className={styles.focusCard}>
        <div className={styles.focusTop}>
          <span className={styles.eyebrow}><Sparkles size={15}/>Today’s focus</span>
          <span className={styles.focusStatus}>{dueWords.length ? 'Review ready' : 'On track'}</span>
        </div>
        <div className={styles.focusBody}>
          <div>
            <strong>{dueWords.length}</strong>
            <h2>{dueWords.length === 1 ? 'word needs attention' : 'words need attention'}</h2>
            <p>{dueWords.length ? 'Your queue is ordered by urgency and memory strength.' : 'Nothing is overdue. A short practice session will reinforce your progress.'}</p>
          </div>
          <div className={styles.progressRing} style={{ background: ringBackground }}><span><strong>{knownPercent}%</strong><small>known</small></span></div>
        </div>
        <footer>
          <span>{nextWord ? <>Next up: <strong>{nextWord.word}</strong> · {nextWord.translation}</> : 'Add your first word to begin.'}</span>
        </footer>
      </article>

      <div className={styles.metrics}>
        <Metric icon={<Layers3/>} label="Vocabulary" value={words.length} note={`${folders.length} collections`}/>
        <Metric icon={<Brain/>} label="Mastered" value={learned} note={`${knownPercent}% of all words`} tone="success"/>
        <Metric icon={<Target/>} label="Accuracy" value={reviews ? `${accuracy}%` : '—'} note={reviews ? `${reviews} total answers` : 'Complete a session'} tone="accent"/>
        <Metric icon={<Flame/>} label="Current streak" value={`${streak}d`} note={streak ? 'Keep it alive today' : 'Start a new streak'} tone="warning"/>
      </div>
    </section>

    <section className={styles.contentGrid}>
      <article className={styles.panel}>
        <header className={styles.panelHeader}><div><span>Collections</span><h2>Continue where you left off</h2></div><button type="button" onClick={() => navigate('/folders')}>View all<ChevronRight size={16}/></button></header>
        <div className={styles.folderList}>
          {folderStats.slice(0, 5).map(({ folder, count, due, percent }) => <button key={folder.id} type="button" onClick={() => navigate(`/study?folder=${folder.id}`)}>
            <span className={styles.folderBadge} style={{ background: `${folder.color}18`, color: folder.color }}>{folder.icon}</span>
            <span className={styles.folderCopy}><strong>{folder.name}</strong><small>{count} words · {due ? `${due} due` : 'up to date'}</small></span>
            <span className={styles.folderProgress}><i style={{ width: `${percent}%`, background: folder.color }}/></span>
            <em>{percent}%</em><ChevronRight size={17}/>
          </button>)}
          {folderStats.length === 0 && <div className={styles.emptyState}><FolderOpen/><strong>No collections yet</strong><span>Create a folder to organize your vocabulary.</span><Button onClick={() => navigate('/folders')}>Create collection</Button></div>}
        </div>
      </article>

      <article className={`${styles.panel} ${styles.activityPanel}`}>
        <header className={styles.panelHeader}><div><span>Last 7 days</span><h2>Learning activity</h2></div><TrendingUp size={20}/></header>
        <div className={styles.chart}>
          {activity.map((item) => <div key={item.label} className={item.today ? styles.today : ''} title={`${item.count} cards in ${item.sessions} sessions`}>
            <span>{item.count || ''}</span><i style={{ height: `${Math.max(item.count ? 16 : 5, item.count / maxActivity * 100)}%` }}/><small>{item.label}</small>
          </div>)}
        </div>
        <div className={styles.activitySummary}>
          <div><CalendarDays/><span><strong>{activity.reduce((sum, item) => sum + item.sessions, 0)}</strong><small>sessions this week</small></span></div>
          <div><BookOpen/><span><strong>{activity.reduce((sum, item) => sum + item.count, 0)}</strong><small>cards reviewed</small></span></div>
          <div><Clock3/><span><strong>{average ? `${average.toFixed(1)}s` : '—'}</strong><small>average answer</small></span></div>
        </div>
      </article>
    </section>

    <section className={styles.lowerGrid}>
      <article className={styles.panel}>
        <header className={styles.panelHeader}><div><span>Memory health</span><h2>Knowledge distribution</h2></div></header>
        <div className={styles.distributionBar} aria-label="Knowledge distribution"><i className={styles.knownBar} style={{ width: `${words.length ? learned / words.length * 100 : 0}%` }}/><i className={styles.learningBar} style={{ width: `${words.length ? learning / words.length * 100 : 0}%` }}/><i className={styles.weakBar} style={{ width: `${words.length ? weak / words.length * 100 : 0}%` }}/></div>
        <div className={styles.legend}>
          <div><span className={styles.knownDot}/><p><strong>{learned}</strong> Known</p><em>{words.length ? Math.round(learned / words.length * 100) : 0}%</em></div>
          <div><span className={styles.learningDot}/><p><strong>{learning}</strong> Learning</p><em>{words.length ? Math.round(learning / words.length * 100) : 0}%</em></div>
          <div><span className={styles.weakDot}/><p><strong>{weak}</strong> New / weak</p><em>{words.length ? Math.round(weak / words.length * 100) : 0}%</em></div>
        </div>
      </article>

      <article className={styles.panel}>
        <header className={styles.panelHeader}><div><span>History</span><h2>Recent sessions</h2></div></header>
        {activeSession && <button className={styles.activeSessionCard} type="button" onClick={() => navigate('/study')}>
          <span><Play size={17}/></span>
          <span><strong>Unfinished session</strong><small>{Math.min(activeSession.index, activeSession.total)} of {activeSession.total} cards completed · {activeSession.mode.replaceAll('-', ' ')}</small></span>
          <em>Continue</em><ChevronRight size={17}/>
        </button>}
        <div className={styles.sessionList}>
          {recentSessions.map((session) => {
            const folder = folders.find((item) => item.id === session.folderId);
            const sessionAccuracy = session.count ? Math.round(session.correct / session.count * 100) : 0;
            return <button key={session.id} type="button" onClick={() => setSelectedSession(session)}>
              <span className={sessionAccuracy >= 80 ? styles.sessionGood : styles.sessionMedium}><Check size={15}/></span>
              <span><strong>{folder?.name || 'Mixed review'}</strong><small>{new Date(session.date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })} · {session.mode}</small></span>
              <em>{session.correct}/{session.count}</em><small>{sessionAccuracy}%</small><ChevronRight size={16}/>
            </button>;
          })}
          {recentSessions.length === 0 && <div className={styles.emptyState}><CalendarDays/><strong>No sessions yet</strong><span>Your completed study sessions will appear here.</span></div>}
        </div>
      </article>
    </section>

    {selectedSession && <div className={styles.sessionOverlay} onMouseDown={(event) => { if (event.currentTarget === event.target) setSelectedSession(null); }}>
      <section className={styles.sessionModal}>
        <header><div><small>SESSION RESULTS</small><h2>{new Date(selectedSession.date).toLocaleString()}</h2><p>{selectedSession.correct}/{selectedSession.count} correct · {selectedSession.averageTime.toFixed(1)} s average</p></div><button type="button" onClick={() => setSelectedSession(null)} aria-label="Close"><X/></button></header>
        <div className={styles.answerList}>{(selectedSession.answers || []).map((answer, index) => <article key={`${answer.wordId}-${index}`} className={answer.correct ? styles.answerCorrect : styles.answerWrong}><div><span>{answer.correct ? 'Correct' : 'Wrong'}</span><strong>{answer.word}</strong><small>{answer.translation}</small></div><dl><div><dt>Question</dt><dd>{answer.prompt || '—'}</dd></div><div><dt>Your answer</dt><dd>{answer.selectedAnswer || 'I don’t know'}</dd></div>{!answer.correct && <div><dt>Correct answer</dt><dd>{answer.correctAnswer}</dd></div>}<div><dt>Time</dt><dd>{answer.seconds.toFixed(1)} s · {answer.attempts} attempt{answer.attempts === 1 ? '' : 's'}</dd></div></dl></article>)}{!(selectedSession.answers || []).length && <p className={styles.emptyText}>Detailed answers were not recorded for this older session.</p>}</div>
      </section>
    </div>}
  </>;
}

function Metric({ icon, label, value, note, tone = 'default' }: { icon: React.ReactNode; label: string; value: string | number; note: string; tone?: 'default' | 'success' | 'accent' | 'warning' }) {
  return <article className={`${styles.metric} ${styles[tone]}`}><span>{icon}</span><div><small>{label}</small><strong>{value}</strong><em>{note}</em></div></article>;
}
